INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C1','kor',2,1,'u2',1,'낱말의 이름과 특징 잇기 — 가랑비·이슬비·장대비·단비처럼 같은 것도 모습·쓰임(특징)에 따라 이름이 다르고, 이름에는 그렇게 붙은 까닭이 있음을 알기',ARRAY['2국05-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C2','kor',2,1,'u2',1,'첫 글자가 같은 낱말 모으기 — 낱말의 맨 앞 글자를 살펴 같은 글자로 시작하는 낱말을 모으고(비누·비행기·비빔밥), 모은 낱말로 짧은 말을 만들며 말의 재미를 느끼기',ARRAY['2국05-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C3','kor',2,1,'u2',3,'꼬리따기 말놀이 — 「사과는 빨개, 빨가면 딸기」처럼 바로 앞말에서 떠오르는 것을 이어 말해 말이 꼬리에 꼬리를 물게 하기',ARRAY['2국05-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C4','kor',2,1,'u2',3,'다섯 글자 말놀이·말 덧붙이기 — 하고 싶은 말을 글자 수(띄어쓰기 빼고)를 세어 다섯 글자로 만들고, 앞 사람 말을 그대로 되풀이한 뒤 한 가지씩 더해 말하기',ARRAY['2국05-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C5','kor',2,1,'u2',3,'말놀이 규칙과 좋은 점 — 차례를 기다리고 친구 말을 끝까지 듣고 놀리지 않으며 함께 즐기기, 말놀이로 여러 낱말을 익히고 친구와 함께 웃을 수 있음을 알기',ARRAY['2국05-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C6','kor',2,1,'u2',6,'주변에서 낱말 찾기 — 교실·부엌·공원 같은 장소를 떠올려 그곳에서 볼 수 있는 낱말을 찾고, 뒤섞인 글자를 바르게 맞추어 숨은 낱말 찾기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C7','kor',2,1,'u2',6,'낱말로 문장·줄줄이 이야기 만들기 — 낱말을 「누가 무엇을 어찌해요」로 이어 문장을 만들고, 친구 문장을 잘 듣고 앞 문장과 이어지게 한 문장씩 더해 이야기 만들기',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C8','kor',2,1,'u2',8,'글 읽고 내용·흉내 내는 말 찾기 — 글에서 누가·무엇을·어떻게 했는지 찾고, 소리를 흉내 낸 말(맴맴·지글지글)과 모양을 흉내 낸 말(깡충깡충·데굴데굴)을 찾아 글을 생생하게 만드는 재미를 느끼기',ARRAY['2국02-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C9','kor',2,1,'u2',8,'글 읽고 생각·느낌 표현하기 — 재미있는 장면·문장을 골라 떠오른 내 경험과 까닭을 들어 생각이나 느낌을 말하고, 친구의 다른 느낌도 인정하기',ARRAY['2국02-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C10','kor',2,1,'u2',10,'좋아하는 문장 소개하기·책갈피 — 책 제목 → 좋아하는 문장 → 좋아하는 까닭 차례로 소개하고, 마음에 드는 짧은 문장 한 줄을 적어 책갈피 만들기',ARRAY['2국03-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u2-C11','kor',2,1,'u2',12,'낱말로 재미있는 이름 짓기 — 소리·모양 흉내 말을 넣거나 같은 소리를 되풀이하고 무엇의 특징(맛·모양)을 살려 재미있는 이름을 짓고, 친구를 놀리는 말은 쓰지 않기',ARRAY['2국05-01']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X01','kor',2,'u2',ARRAY['K2-1-u2-C1']::text[],'이름과 특징을 거꾸로 잇는다 — 가랑비를 굵은 비로, 장대비를 가는 비로 여기거나 이름에 까닭이 없다고 여긴다','이름 속 낱말(장대·이슬·단)이 무엇을 닮았는지 먼저 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X02','kor',2,'u2',ARRAY['K2-1-u2-C2']::text[],'첫 글자 대신 끝 글자나 가운데 글자가 같은 낱말을 고른다(「비」로 시작 → 나비·제비)','낱말의 맨 앞 글자에 손가락을 대고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X03','kor',2,'u2',ARRAY['K2-1-u2-C2']::text[],'자음자만 같으면 같은 글자로 여긴다(바·버·보를 같은 첫 글자로)','첫 글자를 통째로 소리 내어 견주기 — 바, 버, 보는 다른 글자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X04','kor',2,'u2',ARRAY['K2-1-u2-C3']::text[],'꼬리따기에서 앞말에서 떠오르지 않는 엉뚱한 말을 붙인다(빨가면 바나나)','「빨가면?」 하고 앞말을 한 번 더 말한 뒤 떠오르는 것 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X05','kor',2,'u2',ARRAY['K2-1-u2-C3']::text[],'꼬리따기에서 바로 앞말이 아니라 맨 처음 낱말로 돌아가거나 같은 말을 되풀이한다','꼬리는 늘 바로 앞 친구의 마지막 말에서 이어 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X06','kor',2,'u2',ARRAY['K2-1-u2-C4']::text[],'글자 수를 셀 때 낱말 수로 세거나 띄어 쓴 칸·문장 부호까지 센다','글자 하나에 손가락 하나씩 접으며 세기 — 빈칸은 세지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X07','kor',2,'u2',ARRAY['K2-1-u2-C4']::text[],'말 덧붙이기에서 앞 사람 말을 빠뜨리거나 차례를 바꾸고 새것만 말한다','앞 사람 말을 처음부터 그대로 한 번 말하고 끝에 하나 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X08','kor',2,'u2',ARRAY['K2-1-u2-C5','K2-1-u2-C11']::text[],'말놀이는 이기는 것이 가장 중요하다고 여겨 차례를 무시하고 끼어들거나 혼자 정한다','「지금 누구 차례지? 다 같이 즐겁나?」 먼저 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X09','kor',2,'u2',ARRAY['K2-1-u2-C5','K2-1-u2-C10','K2-1-u2-C11']::text[],'친구 말이 틀리거나 우스우면 놀리고, 친구를 놀리는 말로 말놀이·이름 짓기를 한다','「이 말을 들으면 친구가 기분 좋을까?」 한 번 묻고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X10','kor',2,'u2',ARRAY['K2-1-u2-C6']::text[],'장소와 어울리지 않는 낱말을 그 장소의 낱말로 고른다(부엌 — 칠판)','그 장소에 서 있다고 떠올리고 눈앞에 보이는 것만 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X11','kor',2,'u2',ARRAY['K2-1-u2-C6']::text[],'뒤섞인 글자를 맞출 때 놓인 순서대로 읽거나 글자를 빠뜨리고 더한다','글자 카드를 모두 한 번씩 썼는지 하나씩 지우며 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X12','kor',2,'u2',ARRAY['K2-1-u2-C7']::text[],'낱말만 늘어놓아 문장이 되지 않게 말한다(토끼 당근 먹어)','「누가? 무엇을? 어찌해요?」로 이어 끝까지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X13','kor',2,'u2',ARRAY['K2-1-u2-C7']::text[],'줄줄이 이야기에 앞 문장·인물과 관계없는 문장을 이어 이야기가 끊긴다','앞 친구 문장의 인물 이름을 넣어 다음 문장 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X14','kor',2,'u2',ARRAY['K2-1-u2-C8','K2-1-u2-C9','K2-1-u2-C10']::text[],'글에 없는 내용을 있다고 하거나 글의 인물·일을 바꾸어 말한다','답을 고르기 전에 글에서 그 말을 찾아 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X15','kor',2,'u2',ARRAY['K2-1-u2-C8','K2-1-u2-C11']::text[],'흉내 내는 말이 아닌 낱말(여름날·시원하다·강아지)을 흉내 내는 말로 여기거나 무엇의 소리·모양인지 헷갈린다','소리 내어 따라 했을 때 소리나 모습이 들리고 보이면 흉내 내는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X16','kor',2,'u2',ARRAY['K2-1-u2-C9']::text[],'느낌을 까닭 없이 말하거나 글과 반대로 짐작하고, 나와 다른 느낌은 틀렸다고 여긴다','「어느 장면에서? 왜?」를 붙여 말하고 친구 느낌은 「그럴 수 있구나」로 받기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X17','kor',2,'u2',ARRAY['K2-1-u2-C10']::text[],'책을 소개할 때 제목·좋아하는 문장·까닭을 빠뜨리거나, 책갈피에 책을 통째로 옮겨 적는다','「제목 → 문장 → 까닭」 세 손가락을 접으며 소개하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X18','kor',2,'u2',ARRAY['K2-1-u2-C11']::text[],'무엇을 파는지도, 소리의 재미도 드러나지 않는 이름(가게1호·음식 파는 곳)도 재미있는 이름이라고 여긴다','이름만 듣고 무엇인지 떠오르는지, 소리 내어 읽으면 재미있는지 두 번 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u2-X19','kor',2,'u2',ARRAY['K2-1-u2-C2','K2-1-u2-C5','K2-1-u2-C6','K2-1-u2-C7','K2-1-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 다른 것↔같은 것, 어울리지 않는 것↔어울리는 것, 지키지 못한↔지킨','물음의 「다른·않는·못한」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#1','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',1,'mc','auto','가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"가랑비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["가늘게 내리는 비는 가랑비예요.","장대비는 굵고 세차게, 단비는 꼭 필요할 때 내리는 비예요.","비가 내리는 모습을 보고 이름을 떠올려요."],"variant_rule":{"alt":[{"stem":"굵고 세차게 내리는 비를 무엇이라고 하나요?","options":[{"t":"장대비","correct":true},{"t":"이슬비","mis":"K2-1-u2-X01"},{"t":"가랑비","mis":"K2-1-u2-X01"}],"explanation":["굵고 세차게 내리는 비는 장대비예요.","이슬비와 가랑비는 가늘게 내리는 비예요.","긴 장대처럼 굵은 빗줄기를 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#2','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',1,'mc','auto','메마른 땅에 꼭 필요할 때 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":2,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"메마른 땅에 꼭 필요할 때 내리는 비를 무엇이라고 하나요?","options":[{"t":"단비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"이슬비","mis":"K2-1-u2-X01"}],"explanation":["꼭 필요할 때 내려 반가운 비는 단비예요.","장대비는 굵게, 이슬비는 아주 가늘게 내리는 비예요.","이름에는 그렇게 부르는 까닭이 있어요."],"variant_rule":{"alt":[{"stem":"이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"이슬비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["이슬처럼 가늘게 내리는 비는 이슬비예요.","장대비는 굵고 세차게 내리고, 단비는 꼭 필요할 때 내려요.","이름 속 「이슬」이 특징을 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#3','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',1,'mc','auto','「비」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],true,'{"seq":3,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「비」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"비누","correct":true},{"t":"나비","mis":"K2-1-u2-X02"},{"t":"버스","mis":"K2-1-u2-X03"}],"explanation":["비누는 첫 글자가 「비」예요.","나비는 「비」가 끝에 있고, 버스는 「버」로 시작해요.","낱말의 맨 앞 글자를 살펴요."],"variant_rule":{"alt":[{"stem":"「가」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"아가","mis":"K2-1-u2-X02"},{"t":"고래","mis":"K2-1-u2-X03"}],"explanation":["가방은 첫 글자가 「가」예요.","아가는 「가」가 끝에 있고, 고래는 「고」로 시작해요.","낱말의 맨 앞 글자를 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#4','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',1,'ox','auto','「나비」는 「비」로 시작하는 낱말이에요.',ARRAY['K2-1-u2-X02']::text[],true,'{"seq":4,"concept":"K2-1-u2-C2","difficulty":1,"kind":"ox","stem":"「나비」는 「비」로 시작하는 낱말이에요.","answer":"X","reason_options":[{"t":"첫 글자가 「나」이고 「비」는 끝 글자이니까","correct":true},{"t":"「비」가 들어 있으니까","mis":"K2-1-u2-X02"}],"mis":"K2-1-u2-X02","explanation":["나비의 첫 글자는 「나」예요.","글자가 들어 있다고 그 글자로 시작하는 것은 아니에요.","맨 앞 글자를 손가락으로 짚어 봐요."],"variant_rule":{"alt":[{"stem":"「바나나」는 「바」로 시작하는 낱말이에요.","answer":"O","reason_options":[{"t":"맨 앞 글자가 「바」이니까","correct":true},{"t":"「나」가 두 번 나오니까","mis":"K2-1-u2-X02"}],"explanation":["바나나의 맨 앞 글자는 「바」예요.","몇 번 나오는지가 아니라 맨 앞 글자를 봐요.","그래서 「바」로 시작하는 낱말이 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#5','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'match','auto','비의 이름과 특징을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C1","difficulty":2,"kind":"match","stem":"비의 이름과 특징을 알맞게 이어 보세요.","pairs":[{"l":"가랑비","r":"가늘게 내려요"},{"l":"장대비","r":"굵고 세차게 내려요"},{"l":"단비","r":"꼭 필요할 때 내려요"}],"mis":"K2-1-u2-X01","explanation":["가랑비는 가늘게 내리는 비예요.","장대비는 굵고 세차게 내리는 비예요.","단비는 꼭 필요할 때 내리는 반가운 비예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비의 이름과 특징을 알맞게 이어 보세요.","pairs":[{"l":"이슬비","r":"이슬처럼 아주 가늘게 내려요"},{"l":"장대비","r":"장대처럼 굵게 쏟아져요"},{"l":"단비","r":"가뭄 끝에 반갑게 내려요"}],"explanation":["이슬비는 이슬처럼 아주 가늘게 내려요.","장대비는 장대처럼 굵게 쏟아져요.","단비는 꼭 필요할 때 내려 반가운 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#6','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],true,'{"seq":6,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"사과 · 사자 · 사탕","correct":true},{"t":"사과 · 과자 · 자두","mis":"K2-1-u2-X02"},{"t":"사과 · 소금 · 수박","mis":"K2-1-u2-X03"}],"explanation":["사과·사자·사탕은 모두 「사」로 시작해요.","사과·과자·자두는 끝 글자를 이은 것이고, 소금·수박은 「소」·「수」로 시작해요.","맨 앞 글자가 모두 같아야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"고래 · 고구마 · 고양이","correct":true},{"t":"고구마 · 마늘 · 늘보","mis":"K2-1-u2-X02"},{"t":"고래 · 기차 · 구두","mis":"K2-1-u2-X03"}],"explanation":["고래·고구마·고양이는 모두 「고」로 시작해요.","고구마·마늘·늘보는 끝 글자를 이은 것이고, 기차·구두는 「기」·「구」로 시작해요.","맨 앞 글자가 모두 같아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#7','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',2,'sa','auto','비누, 비행기, 비빔밥은 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C2","difficulty":2,"kind":"sa","stem":"비누, 비행기, 비빔밥은 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.","answer":["비"],"explanation":["세 낱말은 모두 「비」로 시작해요.","맨 앞 글자만 보면 돼요.","첫 글자가 같은 낱말을 모으는 것도 말놀이예요."],"variant_rule":{"alt":[{"stem":"가방, 가위, 가지는 모두 어떤 글자로 시작하나요? 한 글자로 써 보세요.","answer":["가"],"explanation":["세 낱말은 모두 「가」로 시작해요.","맨 앞 글자만 보면 돼요.","같은 글자로 시작하는 낱말을 더 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#8','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'mc','auto','「단비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":8,"concept":"K2-1-u2-C1","difficulty":2,"kind":"mc","stem":"「단비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"꼭 필요할 때 내려 반가운 비라서","correct":true},{"t":"굵고 세차게 쏟아지는 비라서","mis":"K2-1-u2-X01"},{"t":"이슬처럼 아주 가늘게 내리는 비라서","mis":"K2-1-u2-X01"}],"explanation":["단비는 메마른 땅에 꼭 필요할 때 내리는 비예요.","굵게 쏟아지는 비는 장대비, 아주 가는 비는 이슬비예요.","이름에는 특징이 담겨 있어요."],"variant_rule":{"alt":[{"stem":"「장대비」라는 이름이 붙은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"긴 장대처럼 굵고 세차게 내리는 비라서","correct":true},{"t":"가늘게 조용히 내리는 비라서","mis":"K2-1-u2-X01"},{"t":"꼭 필요할 때 내리는 비라서","mis":"K2-1-u2-X01"}],"explanation":["장대비는 굵고 세차게 쏟아지는 비예요.","가늘게 내리는 비는 가랑비, 꼭 필요할 때 내리는 비는 단비예요.","이름 속 「장대」가 특징을 알려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#9','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C1',2,'ox','auto','「장대비」는 가늘고 조용히 내리는 비예요.',ARRAY['K2-1-u2-X01']::text[],true,'{"seq":9,"concept":"K2-1-u2-C1","difficulty":2,"kind":"ox","stem":"「장대비」는 가늘고 조용히 내리는 비예요.","answer":"X","reason_options":[{"t":"장대비는 굵고 세차게 내리는 비이니까","correct":true},{"t":"비는 이름만 다르고 모두 똑같으니까","mis":"K2-1-u2-X01"}],"mis":"K2-1-u2-X01","explanation":["장대비는 굵고 세차게 쏟아지는 비예요.","가늘게 내리는 비는 가랑비나 이슬비예요.","이름마다 특징이 달라요."],"variant_rule":{"alt":[{"stem":"같은 비라도 내리는 모습에 따라 이름이 달라요.","answer":"O","reason_options":[{"t":"특징을 보고 이름을 붙이니까","correct":true},{"t":"이름은 아무렇게나 붙이니까","mis":"K2-1-u2-X01"}],"explanation":["비가 내리는 모습이 다르면 이름도 달라요.","이름에는 그렇게 부르는 까닭이 있어요.","특징을 보면 이름을 떠올릴 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_basic#10','kor',2,1,'u2','L01','g2_1_kor_u2_L01_basic','lesson_basic','K2-1-u2-C2',3,'error','auto','「바」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X03','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C2","difficulty":3,"kind":"error","stem":"「바」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「보물!」","correct":true,"mis_target":"K2-1-u2-X03"},{"t":"다은 — 「바지!」","mis":"K2-1-u2-X19"},{"t":"서윤 — 「바다!」","mis":"K2-1-u2-X19"}],"explanation":["보물은 「보」로 시작해요.","「바」와 「보」는 자음자는 같아도 다른 글자예요.","다은이와 서윤이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"「구」로 시작하는 낱말을 말하는 놀이를 했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「야구!」","correct":true,"mis_target":"K2-1-u2-X02"},{"t":"하린 — 「구름!」","mis":"K2-1-u2-X19"},{"t":"민호 — 「구두!」","mis":"K2-1-u2-X19"}],"explanation":["야구는 「야」로 시작하고 「구」는 끝 글자예요.","맨 앞 글자가 「구」여야 해요.","하린이와 민호는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#1','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',2,'mc','auto','「보슬비」라는 이름에 어울리는 특징은 어느 것인가요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":2,"kind":"mc","stem":"「보슬비」라는 이름에 어울리는 특징은 어느 것인가요?","options":[{"t":"보슬보슬 가늘고 부드럽게 내려요","correct":true},{"t":"우르르 쾅쾅 세차게 쏟아져요","mis":"K2-1-u2-X01"},{"t":"굵은 우박이 섞여 떨어져요","mis":"K2-1-u2-X01"}],"explanation":["「보슬보슬」은 가늘고 부드럽게 내리는 모양이에요.","세차게 쏟아지는 비는 장대비에 가까워요.","이름 속 흉내 내는 말이 특징을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#2','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',2,'mc','auto','첫 글자가 다른 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"노루","correct":true},{"t":"나비","mis":"K2-1-u2-X19"},{"t":"나팔","mis":"K2-1-u2-X19"}],"explanation":["노루만 「노」로 시작해요.","나비와 나팔은 「나」로 시작해요.","「다른 것」을 묻는지 물음을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#3','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'mc','auto','「비」로 시작하는 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":3,"concept":"K2-1-u2-C2","difficulty":3,"kind":"mc","stem":"「비」로 시작하는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"비누 · 비옷 · 비둘기","correct":true},{"t":"나비 · 제비 · 비누","mis":"K2-1-u2-X02"},{"t":"비누 · 부채 · 바다","mis":"K2-1-u2-X03"}],"explanation":["비누·비옷·비둘기는 모두 맨 앞 글자가 「비」예요.","나비·제비는 「비」가 끝에 있고, 부채·바다는 「부」·「바」로 시작해요.","세 낱말 모두 맨 앞 글자를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#4','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',3,'mc','auto','창밖에 빗방울이 「톡톡」 작게 떨어져요. 이 모습에 어울리게 새로 지은 비 이름은 어느 것인가요?',ARRAY['K2-1-u2-X01','K2-1-u2-X18']::text[],false,'{"seq":4,"concept":"K2-1-u2-C1","difficulty":3,"kind":"mc","stem":"창밖에 빗방울이 「톡톡」 작게 떨어져요. 이 모습에 어울리게 새로 지은 비 이름은 어느 것인가요?","options":[{"t":"톡톡비","correct":true},{"t":"콸콸비","mis":"K2-1-u2-X01"},{"t":"첫째비","mis":"K2-1-u2-X18"}],"explanation":["톡톡 떨어지는 모습이 이름에 드러나요.","콸콸비는 세차게 쏟아지는 모습이고, 첫째비는 모습이 드러나지 않아요.","특징이 드러나게 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#5','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'ox','auto','첫 글자 말놀이는 맨 앞 글자가 같은 낱말을 모으는 놀이예요.',ARRAY['K2-1-u2-X02']::text[],false,'{"seq":5,"concept":"K2-1-u2-C2","difficulty":3,"kind":"ox","stem":"첫 글자 말놀이는 맨 앞 글자가 같은 낱말을 모으는 놀이예요.","answer":"O","reason_options":[{"t":"낱말의 맨 앞 글자를 보고 모으니까","correct":true},{"t":"어느 자리든 같은 글자가 하나라도 있으면 되니까","mis":"K2-1-u2-X02"}],"mis":"K2-1-u2-X02","explanation":["첫 글자 말놀이는 맨 앞 글자를 봐요.","가운데나 끝 글자가 같은 것은 첫 글자 말놀이가 아니에요.","비누·비행기·비빔밥처럼 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#6','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',3,'error','auto','친구들이 비 이름의 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X01','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C1","difficulty":3,"kind":"error","stem":"친구들이 비 이름의 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지후 — 「이슬비는 굵고 세차게 내려서 붙은 이름이야.」","correct":true,"mis_target":"K2-1-u2-X01"},{"t":"서윤 — 「단비는 꼭 필요할 때 내려서 붙은 이름이야.」","mis":"K2-1-u2-X19"},{"t":"시우 — 「장대비는 장대처럼 굵게 내려서 붙은 이름이야.」","mis":"K2-1-u2-X19"}],"explanation":["이슬비는 이슬처럼 아주 가늘게 내리는 비예요.","굵고 세차게 내리는 비는 장대비예요.","서윤이와 시우는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#7','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',3,'mc','auto','「바」로 시작하는 낱말을 모두 바르게 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X03','K2-1-u2-X02']::text[],false,'{"seq":7,"concept":"K2-1-u2-C2","difficulty":3,"kind":"mc","stem":"「바」로 시작하는 낱말을 모두 바르게 모은 것은 어느 것인가요?","options":[{"t":"바람 · 바위 · 바늘","correct":true},{"t":"바람 · 버섯 · 보리","mis":"K2-1-u2-X03"},{"t":"바람 · 가방 · 나방","mis":"K2-1-u2-X02"}],"explanation":["바람·바위·바늘은 모두 「바」로 시작해요.","버섯·보리는 「버」·「보」로, 가방·나방은 「가」·「나」로 시작해요.","첫 글자를 통째로 소리 내어 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#8','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'mc','auto','두 친구가 햇빛이 날 때 잠깐 내리는 비에 이름을 지었어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#9','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C2',4,'essay','teacher','「사」로 시작하는 낱말을 세 개 모아 쓰고, 그 낱말을 넣어 짧은 문장을 하나 만들어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C2","difficulty":4,"kind":"essay","stem":"「사」로 시작하는 낱말을 세 개 모아 쓰고, 그 낱말을 넣어 짧은 문장을 하나 만들어 보세요.","answer_guide":{"answer":"예: 사과, 사자, 사탕 / 사자가 사과와 사탕을 먹어요.","scoring_points":["맨 앞 글자가 「사」인 낱말을 세 개 썼는가","모은 낱말을 넣어 문장으로 썼는가","문장 끝에 마침표를 찍었는가"]},"explanation":["첫 글자 「사」.","낱말 넣어 문장.","마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L01_challenge#10','kor',2,1,'u2','L01','g2_1_kor_u2_L01_challenge','lesson_challenge','K2-1-u2-C1',4,'essay','teacher','비가 내리는 모습을 떠올려 새로운 비 이름을 짓고, 그렇게 지은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C1","difficulty":4,"kind":"essay","stem":"비가 내리는 모습을 떠올려 새로운 비 이름을 짓고, 그렇게 지은 까닭을 써 보세요.","answer_guide":{"answer":"예: 「또르르비」 — 빗방울이 창문을 또르르 굴러 내려가는 모습이 떠올라서 지었어요.","scoring_points":["비 이름을 새로 지었는가","비가 내리는 모습(특징)이 이름에 드러나는가","지은 까닭을 썼는가"]},"explanation":["새 이름.","특징이 드러남.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#1','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#2','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],true,'{"seq":2,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"오늘참좋다","correct":true},{"t":"안녕","mis":"K2-1-u2-X06"},{"t":"고마워","mis":"K2-1-u2-X06"}],"explanation":["오·늘·참·좋·다, 다섯 글자예요.","「안녕」은 두 글자, 「고마워」는 세 글자예요.","글자 하나에 손가락 하나씩 접어 세요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"참잘했어요","correct":true},{"t":"좋아","mis":"K2-1-u2-X06"},{"t":"반가워친구야","mis":"K2-1-u2-X06"}],"explanation":["참·잘·했·어·요, 다섯 글자예요.","「좋아」는 두 글자, 「반가워친구야」는 여섯 글자예요.","글자 하나에 손가락 하나씩 접어 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#3','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 방법은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],true,'{"seq":3,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 방법은 어느 것인가요?","options":[{"t":"내 차례를 기다려요","correct":true},{"t":"먼저 말하려고 친구 말을 끊어요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지켜야 모두 즐겁게 놀 수 있어요.","친구 말을 끊거나 놀리면 놀이가 즐겁지 않아요.","말놀이는 함께 즐기는 놀이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말놀이를 바르게 하는 방법은 어느 것인가요?","options":[{"t":"친구 말을 끝까지 들어요","correct":true},{"t":"이기려고 혼자 계속 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말이 틀리면 깔깔 비웃어요","mis":"K2-1-u2-X09"}],"explanation":["친구 말을 끝까지 들어야 이어서 말할 수 있어요.","혼자 말하거나 비웃으면 놀이가 즐겁지 않아요.","함께 즐기는 마음이 가장 중요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#4','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',1,'ox','auto','꼬리따기는 바로 앞말에서 떠오르는 것을 이어 말하는 놀이예요.',ARRAY['K2-1-u2-X04']::text[],true,'{"seq":4,"concept":"K2-1-u2-C3","difficulty":1,"kind":"ox","stem":"꼬리따기는 바로 앞말에서 떠오르는 것을 이어 말하는 놀이예요.","answer":"O","reason_options":[{"t":"앞말에 꼬리를 물듯 이어 가니까","correct":true},{"t":"아무 낱말이나 말하면 되니까","mis":"K2-1-u2-X04"}],"mis":"K2-1-u2-X04","explanation":["꼬리따기는 앞말에서 떠오르는 것을 이어요.","「사과는 빨개, 빨가면 딸기」처럼 이어 가요.","아무 말이나 하면 말이 이어지지 않아요."],"variant_rule":{"alt":[{"stem":"꼬리따기에서는 앞말과 관계없는 말을 해도 돼요.","answer":"X","reason_options":[{"t":"앞말에서 떠오르는 말을 이어야 하니까","correct":true},{"t":"재미만 있으면 되니까","mis":"K2-1-u2-X04"}],"explanation":["꼬리따기는 앞말에 이어 말하는 놀이예요.","관계없는 말을 하면 꼬리가 끊겨요.","앞말을 한 번 더 말하고 떠오르는 것을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#5','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'match','auto','말놀이 이름과 알맞은 설명을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C4","difficulty":2,"kind":"match","stem":"말놀이 이름과 알맞은 설명을 이어 보세요.","pairs":[{"l":"꼬리따기","r":"앞말에서 떠오르는 말을 이어요"},{"l":"다섯 글자 말놀이","r":"다섯 글자로만 말해요"},{"l":"말 덧붙이기","r":"앞 사람 말에 하나씩 더해요"}],"mis":"K2-1-u2-X07","explanation":["꼬리따기는 떠오르는 말을 이어요.","다섯 글자 말놀이는 글자 수를 맞춰요.","말 덧붙이기는 앞 사람 말에 하나씩 더해요."],"variant_rule":{"alt":[{"stem":"말놀이 예와 알맞은 말놀이 이름을 이어 보세요.","pairs":[{"l":"「하늘은 파래, 파라면 바다」","r":"꼬리따기"},{"l":"「안녕친구야」","r":"다섯 글자 말놀이"},{"l":"「시장에 가면 사과도 있고, 배도 있고」","r":"말 덧붙이기"}],"explanation":["파래 → 바다로 이어 가는 것은 꼬리따기예요.","다섯 글자로 맞춘 말은 다섯 글자 말놀이예요.","앞말에 하나씩 더하는 것은 말 덧붙이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#6','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],true,'{"seq":6,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「시장에 가면 사과도 있고, 배도 있고, 감도 있고」","correct":true},{"t":"「시장에 가면 감도 있고」","mis":"K2-1-u2-X07"},{"t":"「시장에 가면 배도 있고, 사과도 있고, 감도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기의 재미예요."],"variant_rule":{"alt":[{"stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「동물원에 가면 사자도 있고, 기린도 있고」","correct":true},{"t":"「동물원에 가면 기린도 있고」","mis":"K2-1-u2-X07"},{"t":"「동물원에 가면 기린도 있고, 사자도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","기억해서 이어 말하는 재미가 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#7','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C4',2,'sa','auto','「고마워친구」는 몇 글자인가요? 숫자로 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C4","difficulty":2,"kind":"sa","stem":"「고마워친구」는 몇 글자인가요? 숫자로 써 보세요.","answer":["5","5글자","다섯","다섯 글자"],"explanation":["고·마·워·친·구, 다섯 글자예요.","글자 하나에 손가락 하나씩 접어 세요.","다섯 글자 말놀이에 쓸 수 있는 말이에요."],"variant_rule":{"alt":[{"stem":"「사랑해요」는 몇 글자인가요? 숫자로 써 보세요.","answer":["4","4글자","네","네 글자"],"explanation":["사·랑·해·요, 네 글자예요.","글자 하나에 손가락 하나씩 접어 세요.","다섯 글자로 만들려면 한 글자를 더해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#8','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',2,'mc','auto','말놀이를 하면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],true,'{"seq":8,"concept":"K2-1-u2-C5","difficulty":2,"kind":"mc","stem":"말놀이를 하면 좋은 점은 어느 것인가요?","options":[{"t":"여러 낱말을 자연스럽게 익혀요","correct":true},{"t":"친구를 이겨서 으쓱해져요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀릴 수 있어요","mis":"K2-1-u2-X09"}],"explanation":["말놀이를 하면 낱말을 많이 만나고 익혀요.","이기거나 놀리는 것이 말놀이의 좋은 점은 아니에요.","친구와 함께 웃으며 말의 재미를 느껴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말놀이를 하면 좋은 점은 어느 것인가요?","options":[{"t":"친구와 함께 웃으며 놀 수 있어요","correct":true},{"t":"혼자 오래 말할 수 있어요","mis":"K2-1-u2-X08"},{"t":"친구 말을 흉내 내며 놀릴 수 있어요","mis":"K2-1-u2-X09"}],"explanation":["말놀이는 친구와 함께 즐기는 놀이예요.","혼자 말하거나 놀리면 함께 즐길 수 없어요.","함께 웃으며 여러 낱말도 익혀요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#9','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C5',2,'ox','auto','말놀이에서 이기려면 친구 말을 끊고 먼저 말해도 돼요.',ARRAY['K2-1-u2-X08']::text[],true,'{"seq":9,"concept":"K2-1-u2-C5","difficulty":2,"kind":"ox","stem":"말놀이에서 이기려면 친구 말을 끊고 먼저 말해도 돼요.","answer":"X","reason_options":[{"t":"차례를 지켜야 모두 즐겁게 놀 수 있으니까","correct":true},{"t":"이기는 것이 가장 중요하니까","mis":"K2-1-u2-X08"}],"mis":"K2-1-u2-X08","explanation":["친구 말을 끊으면 놀이가 엉망이 돼요.","말놀이는 이기기보다 함께 즐기는 놀이예요.","내 차례를 기다려요."],"variant_rule":{"alt":[{"stem":"친구가 꼬리따기를 잘 잇지 못하면 기다려 주거나 도와줘요.","answer":"O","reason_options":[{"t":"함께 즐기는 놀이이니까","correct":true},{"t":"틀렸으니 놀려야 하니까","mis":"K2-1-u2-X09"}],"explanation":["친구가 막히면 기다려 주는 것이 좋아요.","놀리면 친구가 다시 말하고 싶지 않아져요.","「천천히 해.」 하고 말해 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_basic#10','kor',2,1,'u2','L03','g2_1_kor_u2_L03_basic','lesson_basic','K2-1-u2-C3',3,'error','auto','「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「파라면 사과」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"다은 — 「파라면 바다」","mis":"K2-1-u2-X19"},{"t":"서아 — 「파라면 청바지」","mis":"K2-1-u2-X19"}],"explanation":["사과는 파랗지 않아요.","바다와 청바지는 파란 것이라 잘 이어졌어요.","바로 앞말 「파라면」에서 떠오르는 것을 이어요."],"variant_rule":{"alt":[{"stem":"「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"도윤 — 「하야면 토마토」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"하린 — 「하야면 구름」","mis":"K2-1-u2-X19"},{"t":"예린 — 「하야면 우유」","mis":"K2-1-u2-X19"}],"explanation":["토마토는 하얗지 않아요.","구름과 우유는 하얀 것이라 잘 이어졌어요.","바로 앞말 「하야면」에서 떠오르는 것을 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#1','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',2,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#2','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',2,'mc','auto','친구에게 고마운 마음을 다섯 글자로 말한 것은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":2,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"친구에게 고마운 마음을 다섯 글자로 말한 것은 어느 것인가요?","options":[{"t":"정말고마워","correct":true},{"t":"고마워","mis":"K2-1-u2-X06"},{"t":"정말정말고마워","mis":"K2-1-u2-X06"}],"explanation":["정·말·고·마·워, 다섯 글자예요.","「고마워」는 세 글자, 「정말정말고마워」는 일곱 글자예요.","하고 싶은 말을 다섯 글자에 맞추는 재미가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#3','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',3,'mc','auto','말 덧붙이기 놀이를 하고 있어요. 넷째 차례인 시우가 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":3,"concept":"K2-1-u2-C4","difficulty":3,"kind":"mc","stem":"말 덧붙이기 놀이를 하고 있어요. 넷째 차례인 시우가 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고, 갈매기도 있고」","correct":true},{"t":"「바닷가에 가면 갈매기도 있고」","mis":"K2-1-u2-X07"},{"t":"「바닷가에 가면 조개도 있고, 모래도 있고, 갈매기도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말 세 가지를 그대로 말해요.","그다음 끝에 한 가지를 더해요.","하나라도 빠뜨리면 덧붙이기가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"지안","text":"바닷가에 가면 조개도 있고"},{"who":"태민","text":"바닷가에 가면 조개도 있고, 게도 있고"},{"who":"소율","text":"바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고"},{"who":"시우","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#4','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',3,'mc','auto','꼬리따기가 바르게 이어진 것은 어느 것인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X05']::text[],false,'{"seq":4,"concept":"K2-1-u2-C3","difficulty":3,"kind":"mc","stem":"꼬리따기가 바르게 이어진 것은 어느 것인가요?","options":[{"t":"바나나는 노래 → 노라면 병아리 → 병아리는 작아 → 작으면 개미","correct":true},{"t":"바나나는 노래 → 노라면 바다 → 바다는 넓어","mis":"K2-1-u2-X04"},{"t":"바나나는 노래 → 노라면 바나나 → 바나나는 노래","mis":"K2-1-u2-X05"}],"explanation":["노란 것 병아리, 작은 것 개미로 꼬리를 물었어요.","바다는 노랗지 않고, 바나나로 돌아가면 꼬리가 맴돌아요.","바로 앞말에서 떠오르는 새것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#5','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C4',3,'ox','auto','「안녕 친구야」는 띄어 쓴 칸까지 세어 여섯 글자예요.',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":5,"concept":"K2-1-u2-C4","difficulty":3,"kind":"ox","stem":"「안녕 친구야」는 띄어 쓴 칸까지 세어 여섯 글자예요.","answer":"X","reason_options":[{"t":"띄어 쓴 칸은 글자가 아니라서 다섯 글자이니까","correct":true},{"t":"빈칸도 한 글자로 세니까","mis":"K2-1-u2-X06"}],"mis":"K2-1-u2-X06","explanation":["안·녕·친·구·야, 다섯 글자예요.","띄어 쓴 칸은 세지 않아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#6','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',3,'error','auto','친구들이 말놀이를 했어요. 약속을 지키지 못한 친구는 누구인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C5","difficulty":3,"kind":"error","stem":"친구들이 말놀이를 했어요. 약속을 지키지 못한 친구는 누구인가요?","options":[{"t":"지호 — 친구가 생각하는 동안 「빨리 해! 너 졌어!」 하고 놀렸어요","correct":true,"mis_target":"K2-1-u2-X09"},{"t":"하린 — 차례를 기다렸다가 말했어요","mis":"K2-1-u2-X19"},{"t":"도담 — 친구가 막히자 「천천히 해.」 하고 기다렸어요","mis":"K2-1-u2-X19"}],"explanation":["지호는 생각하는 친구를 재촉하고 놀렸어요.","말놀이는 이기기보다 함께 즐기는 놀이예요.","하린이와 도담이는 약속을 잘 지켰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#7','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',3,'mc','auto','꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":7,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「앞말에서 떠오르는 걸 다시 생각해 볼까?」","correct":true},{"t":"「그것도 몰라? 바보야.」","mis":"K2-1-u2-X09"},{"t":"「넌 빠져. 우리끼리 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#8','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',4,'blank','auto','꼬리따기를 이어 가요. 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#9','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C3',4,'essay','teacher','「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 하늘은 파래 → 파라면 바다 → 바다는 넓어 → 넓으면 운동장","scoring_points":["「하늘은 파래」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L03_challenge#10','kor',2,1,'u2','L03','g2_1_kor_u2_L03_challenge','lesson_challenge','K2-1-u2-C5',4,'essay','teacher','친구와 말놀이를 할 때 지킬 약속을 두 가지 쓰고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C5","difficulty":4,"kind":"essay","stem":"친구와 말놀이를 할 때 지킬 약속을 두 가지 쓰고, 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 내 차례를 기다리겠습니다. 친구가 틀려도 놀리지 않겠습니다. 그래야 모두가 즐겁게 놀 수 있기 때문입니다.","scoring_points":["지킬 약속을 두 가지 썼는가","차례·듣기·놀리지 않기 같은 말놀이 약속인가","까닭을 썼는가"]},"explanation":["약속 두 가지.","말놀이 약속.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#1','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'mc','auto','부엌에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":1,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"부엌에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"냄비","correct":true},{"t":"칠판","mis":"K2-1-u2-X10"},{"t":"미끄럼틀","mis":"K2-1-u2-X10"}],"explanation":["냄비는 부엌에서 음식을 할 때 써요.","칠판은 교실, 미끄럼틀은 놀이터에 있어요.","그 장소에 서 있다고 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"교실에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"책상","correct":true},{"t":"국자","mis":"K2-1-u2-X10"},{"t":"그네","mis":"K2-1-u2-X10"}],"explanation":["책상은 교실에서 볼 수 있어요.","국자는 부엌, 그네는 놀이터에 있어요.","그 장소에 서 있다고 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#2','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'mc','auto','뒤섞인 글자 「방 · 가」를 바르게 맞춘 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],true,'{"seq":2,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"뒤섞인 글자 「방 · 가」를 바르게 맞춘 낱말은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"방가","mis":"K2-1-u2-X11"},{"t":"바가","mis":"K2-1-u2-X11"}],"explanation":["글자를 바꾸어 놓으면 「가방」이 돼요.","놓인 차례대로 읽거나 글자를 바꾸면 낱말이 안 돼요.","두 글자를 모두 한 번씩 써요."],"variant_rule":{"alt":[{"stem":"뒤섞인 글자 「끼 · 토」를 바르게 맞춘 낱말은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"끼토","mis":"K2-1-u2-X11"},{"t":"토기","mis":"K2-1-u2-X11"}],"explanation":["글자를 바꾸어 놓으면 「토끼」가 돼요.","놓인 차례대로 읽거나 글자를 바꾸면 안 돼요.","두 글자를 모두 한 번씩 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#3','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',1,'mc','auto','「토끼」와 「당근」으로 만든 문장은 어느 것인가요?',ARRAY['K2-1-u2-X12']::text[],true,'{"seq":3,"concept":"K2-1-u2-C7","difficulty":1,"kind":"mc","stem":"「토끼」와 「당근」으로 만든 문장은 어느 것인가요?","options":[{"t":"토끼가 당근을 먹어요.","correct":true},{"t":"토끼 당근.","mis":"K2-1-u2-X12"},{"t":"당근 토끼 먹어.","mis":"K2-1-u2-X12"}],"explanation":["「누가 무엇을 어찌해요」로 이어 문장을 만들어요.","낱말만 늘어놓으면 문장이 되지 않아요.","토끼가, 당근을처럼 이어 주는 말을 붙여요."],"variant_rule":{"alt":[{"stem":"「강아지」와 「공」으로 만든 문장은 어느 것인가요?","options":[{"t":"강아지가 공을 물어 와요.","correct":true},{"t":"강아지 공.","mis":"K2-1-u2-X12"},{"t":"공 강아지 물어.","mis":"K2-1-u2-X12"}],"explanation":["「누가 무엇을 어찌해요」로 이어 문장을 만들어요.","낱말만 늘어놓으면 문장이 되지 않아요.","강아지가, 공을처럼 이어 주는 말을 붙여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#4','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',1,'ox','auto','놀이터에서 볼 수 있는 낱말에는 「그네」와 「미끄럼틀」이 있어요.',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":4,"concept":"K2-1-u2-C6","difficulty":1,"kind":"ox","stem":"놀이터에서 볼 수 있는 낱말에는 「그네」와 「미끄럼틀」이 있어요.","answer":"O","reason_options":[{"t":"그네와 미끄럼틀은 놀이터에 있으니까","correct":true},{"t":"놀이터에는 냄비와 국자가 있으니까","mis":"K2-1-u2-X10"}],"mis":"K2-1-u2-X10","explanation":["그네와 미끄럼틀은 놀이터에서 볼 수 있어요.","냄비와 국자는 부엌에서 볼 수 있어요.","장소마다 어울리는 낱말이 달라요."],"variant_rule":{"alt":[{"stem":"「냄비」와 「국자」는 교실에서 볼 수 있는 낱말이에요.","answer":"X","reason_options":[{"t":"냄비와 국자는 부엌에서 볼 수 있으니까","correct":true},{"t":"낱말은 어느 장소에서나 똑같으니까","mis":"K2-1-u2-X10"}],"explanation":["냄비와 국자는 부엌에서 써요.","교실에서는 칠판, 책상 같은 낱말을 볼 수 있어요.","장소마다 어울리는 낱말이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#5','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'match','auto','낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C6","difficulty":2,"kind":"match","stem":"낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.","pairs":[{"l":"칠판","r":"교실"},{"l":"냄비","r":"부엌"},{"l":"미끄럼틀","r":"놀이터"}],"mis":"K2-1-u2-X10","explanation":["칠판은 교실에 있어요.","냄비는 부엌에 있어요.","미끄럼틀은 놀이터에 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 그 낱말을 볼 수 있는 장소를 이어 보세요.","pairs":[{"l":"비둘기","r":"공원"},{"l":"칫솔","r":"화장실"},{"l":"장바구니","r":"시장"}],"explanation":["비둘기는 공원에서 볼 수 있어요.","칫솔은 화장실에 있어요.","장바구니는 시장에 들고 가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#6','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',2,'mc','auto','친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],true,'{"seq":6,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「곰은 꿀을 좋아했어요.」","correct":true},{"t":"「자동차가 빵빵 울려요.」","mis":"K2-1-u2-X13"},{"t":"「곰 꿀 나무.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 곰 이야기를 이어 가요.","자동차 이야기는 곰과 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장의 인물을 넣어 이어 말해요."],"variant_rule":{"alt":[{"stem":"친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「다람쥐는 도토리를 나무 구멍에 숨겼어요.」","correct":true},{"t":"「비행기가 하늘을 날아요.」","mis":"K2-1-u2-X13"},{"t":"「다람쥐 도토리 구멍.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 다람쥐 이야기를 이어 가요.","비행기 이야기는 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장의 인물을 넣어 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#7','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'sa','auto','뒤섞인 글자 「자 · 피」를 바르게 맞춘 낱말을 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C6","difficulty":2,"kind":"sa","stem":"뒤섞인 글자 「자 · 피」를 바르게 맞춘 낱말을 써 보세요.","answer":["피자"],"explanation":["「피」와 「자」를 바꾸면 「피자」가 돼요.","두 글자를 모두 한 번씩 썼어요.","숨은 낱말을 찾는 것도 말놀이예요."],"variant_rule":{"alt":[{"stem":"뒤섞인 글자 「차 · 기」를 바르게 맞춘 낱말을 써 보세요.","answer":["기차"],"explanation":["「기」와 「차」를 바꾸면 「기차」가 돼요.","두 글자를 모두 한 번씩 썼어요.","숨은 낱말을 찾는 것도 말놀이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#8','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C6',2,'mc','auto','공원에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],true,'{"seq":8,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"공원에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"나무 · 의자 · 비둘기","correct":true},{"t":"냄비 · 그릇 · 국자","mis":"K2-1-u2-X10"},{"t":"칠판 · 책상 · 분필","mis":"K2-1-u2-X10"}],"explanation":["나무·의자·비둘기는 공원에서 볼 수 있어요.","냄비·그릇·국자는 부엌, 칠판·책상·분필은 교실에 있어요.","공원에 서 있다고 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"바닷가에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"모래 · 조개 · 파도","correct":true},{"t":"그네 · 시소 · 미끄럼틀","mis":"K2-1-u2-X10"},{"t":"칠판 · 책상 · 필통","mis":"K2-1-u2-X10"}],"explanation":["모래·조개·파도는 바닷가에서 볼 수 있어요.","그네·시소는 놀이터, 칠판·필통은 교실에 있어요.","바닷가에 서 있다고 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#9','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',2,'ox','auto','줄줄이 이야기는 앞 친구의 문장을 잘 듣고 이어지게 말해야 해요.',ARRAY['K2-1-u2-X13']::text[],true,'{"seq":9,"concept":"K2-1-u2-C7","difficulty":2,"kind":"ox","stem":"줄줄이 이야기는 앞 친구의 문장을 잘 듣고 이어지게 말해야 해요.","answer":"O","reason_options":[{"t":"그래야 이야기가 자연스럽게 이어지니까","correct":true},{"t":"아무 문장이나 말해도 이야기가 되니까","mis":"K2-1-u2-X13"}],"mis":"K2-1-u2-X13","explanation":["앞 문장과 이어져야 이야기가 돼요.","관계없는 문장을 말하면 이야기가 끊겨요.","친구 문장을 끝까지 잘 들어요."],"variant_rule":{"alt":[{"stem":"「토끼 당근 밭」처럼 낱말만 늘어놓아도 문장이 돼요.","answer":"X","reason_options":[{"t":"「토끼가 당근 밭에 가요.」처럼 이어야 문장이니까","correct":true},{"t":"낱말이 들어 있으면 문장이니까","mis":"K2-1-u2-X12"}],"explanation":["낱말만 늘어놓으면 뜻이 잘 전해지지 않아요.","「누가 무엇을 어찌해요」로 이어야 문장이에요.","이어 주는 말을 붙여 끝까지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_basic#10','kor',2,1,'u2','L06','g2_1_kor_u2_L06_basic','lesson_basic','K2-1-u2-C7',3,'error','auto','친구들이 토끼 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C7","difficulty":3,"kind":"error","stem":"친구들이 토끼 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?","options":[{"t":"시우 — 「자동차가 빵빵 울렸어요.」","correct":true,"mis_target":"K2-1-u2-X13"},{"t":"다은 — 「토끼가 깡충깡충 뛰어갔어요.」","mis":"K2-1-u2-X19"},{"t":"로아 — 「토끼는 당근 밭에 도착했어요.」","mis":"K2-1-u2-X19"}],"explanation":["자동차 이야기는 토끼 이야기와 관계가 없어요.","다은이와 로아는 토끼 이야기를 이어 갔어요.","앞 문장의 인물을 넣어 이어 말해요."],"variant_rule":{"alt":[{"stem":"친구들이 고양이 이야기를 줄줄이 만들었어요. 이야기와 어울리지 않는 문장을 말한 친구는 누구인가요?","options":[{"t":"하람 — 「비행기가 구름 위로 날아갔어요.」","correct":true,"mis_target":"K2-1-u2-X13"},{"t":"은솔 — 「고양이가 털실을 굴리며 놀았어요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「고양이는 털실을 안고 잠이 들었어요.」","mis":"K2-1-u2-X19"}],"explanation":["비행기 이야기는 고양이 이야기와 관계가 없어요.","은솔이와 지안이는 고양이 이야기를 이어 갔어요.","앞 문장의 인물을 넣어 이어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#1','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「크 · 스 · 림 · 아 · 이」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":1,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「크 · 스 · 림 · 아 · 이」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"아이스크림","correct":true},{"t":"아이스림크","mis":"K2-1-u2-X11"},{"t":"아이크림","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「아이스크림」이 돼요.","차례를 잘못 놓거나 「스」를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#2','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',2,'mc','auto','「아기」, 「우유」, 「엄마」로 만든 문장은 어느 것인가요?',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":2,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"「아기」, 「우유」, 「엄마」로 만든 문장은 어느 것인가요?","options":[{"t":"엄마가 아기에게 우유를 줘요.","correct":true},{"t":"아기 우유 엄마.","mis":"K2-1-u2-X12"},{"t":"엄마가 우유.","mis":"K2-1-u2-X12"}],"explanation":["세 낱말을 모두 넣어 「누가 누구에게 무엇을 어찌해요」로 이었어요.","낱말만 늘어놓거나 끝을 맺지 않으면 문장이 아니에요.","이어 주는 말을 붙여 끝까지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#3','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',3,'mc','auto','칠판, 필통, 냄비, 책상 가운데 교실과 어울리지 않는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":3,"concept":"K2-1-u2-C6","difficulty":3,"kind":"mc","stem":"칠판, 필통, 냄비, 책상 가운데 교실과 어울리지 않는 낱말은 어느 것인가요?","options":[{"t":"냄비","correct":true},{"t":"칠판","mis":"K2-1-u2-X19"},{"t":"필통","mis":"K2-1-u2-X19"}],"explanation":["냄비는 부엌에서 쓰는 물건이에요.","칠판, 필통, 책상은 교실에서 볼 수 있어요.","「어울리지 않는」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#4','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":4,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"기차가 칙칙폭폭 달렸어요.","correct":true},{"t":"다람쥐는 가을마다 도토리를 모았어요.","mis":"K2-1-u2-X19"},{"t":"겨울이 되자 다람쥐는 모은 도토리를 먹었어요.","mis":"K2-1-u2-X19"}],"explanation":["기차 이야기는 다람쥐 이야기와 관계가 없어요.","다른 문장은 모두 다람쥐가 한 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["옛날에 다람쥐가 살았어요.","다람쥐는 가을마다 도토리를 모았어요.","기차가 칙칙폭폭 달렸어요.","겨울이 되자 다람쥐는 모은 도토리를 먹었어요."],"title":"친구들과 만든 줄줄이 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#5','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'ox','auto','「곰이 꿀을 먹어요.」와 「곰 꿀 먹어.」는 똑같이 잘 만든 문장이에요.',ARRAY['K2-1-u2-X12']::text[],false,'{"seq":5,"concept":"K2-1-u2-C7","difficulty":3,"kind":"ox","stem":"「곰이 꿀을 먹어요.」와 「곰 꿀 먹어.」는 똑같이 잘 만든 문장이에요.","answer":"X","reason_options":[{"t":"「곰이」, 「꿀을」처럼 이어 주는 말이 있어야 뜻이 잘 전해지니까","correct":true},{"t":"같은 낱말을 썼으니까","mis":"K2-1-u2-X12"}],"mis":"K2-1-u2-X12","explanation":["「곰이 꿀을 먹어요.」는 누가 무엇을 하는지 잘 보여요.","「곰 꿀 먹어.」는 낱말만 늘어놓은 말이에요.","이어 주는 말을 붙이고 끝까지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#6','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',3,'error','auto','친구들이 장소와 낱말을 이어 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X10','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":3,"kind":"error","stem":"친구들이 장소와 낱말을 이어 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「부엌에는 미끄럼틀이 있어요.」","correct":true,"mis_target":"K2-1-u2-X10"},{"t":"지안 — 「교실에는 칠판이 있어요.」","mis":"K2-1-u2-X19"},{"t":"소율 — 「공원에는 비둘기가 있어요.」","mis":"K2-1-u2-X19"}],"explanation":["미끄럼틀은 놀이터에 있어요.","칠판은 교실, 비둘기는 공원에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#7','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',3,'mc','auto','친구들이 줄줄이 이야기를 만들고 있어요. 도윤이가 이어 말할 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":7,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들이 줄줄이 이야기를 만들고 있어요. 도윤이가 이어 말할 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그래서 엄마 펭귄에게 헤엄을 배웠어요.」","correct":true},{"t":"「사과는 빨개요.」","mis":"K2-1-u2-X13"},{"t":"「펭귄 바다 물.」","mis":"K2-1-u2-X12"}],"explanation":["헤엄을 못 치는 아기 펭귄 이야기를 이어 가요.","사과 이야기는 관계가 없고, 낱말만 늘어놓으면 문장이 아니에요.","앞 문장과 이어지게 말해요."],"asset":{"type":"speech","turns":[{"who":"지후","text":"옛날에 아기 펭귄이 살았어요."},{"who":"서윤","text":"아기 펭귄은 헤엄을 못 쳤어요."},{"who":"도윤","text":"( ? )"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#8','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',4,'mc','auto','글자 카드 「자 · 사 · 과 · 사」 네 장을 모두 한 번씩 써서 낱말 두 개를 만들었어요. 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":8,"concept":"K2-1-u2-C6","difficulty":4,"kind":"mc","stem":"글자 카드 「자 · 사 · 과 · 사」 네 장을 모두 한 번씩 써서 낱말 두 개를 만들었어요. 알맞은 것은 어느 것인가요?","options":[{"t":"사자, 사과","correct":true},{"t":"사과, 자사","mis":"K2-1-u2-X11"},{"t":"사자, 과자","mis":"K2-1-u2-X11"}],"explanation":["사·자와 사·과로 카드 네 장을 모두 한 번씩 썼어요.","「자사」는 낱말이 아니고, 과자를 만들려면 「자」가 한 장 더 있어야 해요.","카드를 하나씩 지우며 맞춰 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#9','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C7',4,'essay','teacher','「바닷가」, 「조개」, 「파도」를 모두 넣어 이어지는 이야기를 세 문장으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C7","difficulty":4,"kind":"essay","stem":"「바닷가」, 「조개」, 「파도」를 모두 넣어 이어지는 이야기를 세 문장으로 써 보세요.","answer_guide":{"answer":"예: 지우는 바닷가에 놀러 갔어요. / 모래 속에서 예쁜 조개를 주웠어요. / 그때 파도가 철썩 밀려와 발을 적셨어요.","scoring_points":["세 낱말을 모두 넣었는가","문장마다 「누가 무엇을 어찌해요」로 썼는가","세 문장이 이어지는 이야기가 되었는가"]},"explanation":["세 낱말.","문장으로.","이어지는 이야기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L06_challenge#10','kor',2,1,'u2','L06','g2_1_kor_u2_L06_challenge','lesson_challenge','K2-1-u2-C6',4,'essay','teacher','우리 집 부엌이나 우리 교실에서 볼 수 있는 낱말을 세 개 쓰고, 그 가운데 두 낱말을 넣어 문장을 하나 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C6","difficulty":4,"kind":"essay","stem":"우리 집 부엌이나 우리 교실에서 볼 수 있는 낱말을 세 개 쓰고, 그 가운데 두 낱말을 넣어 문장을 하나 만들어 보세요.","answer_guide":{"answer":"예: (부엌) 냄비, 국자, 숟가락 / 엄마가 국자로 냄비 속 국을 떠요.","scoring_points":["한 장소에서 볼 수 있는 낱말을 세 개 썼는가","두 낱말을 넣어 문장으로 썼는가","문장 끝에 마침표를 찍었는가"]},"explanation":["한 장소의 낱말.","두 낱말로 문장.","마침표."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#1','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?',ARRAY['K2-1-u2-X14']::text[],true,'{"seq":1,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?","options":[{"t":"노란 우산","correct":true},{"t":"빨간 모자","mis":"K2-1-u2-X14"},{"t":"파란 비옷","mis":"K2-1-u2-X14"}],"explanation":["글에 「노란 우산을 쓰고」라고 나와 있어요.","모자나 비옷은 글에 나오지 않아요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 눈사람의 코에 붙인 것은 무엇인가요?","options":[{"t":"당근","correct":true},{"t":"단추","mis":"K2-1-u2-X14"},{"t":"솔방울","mis":"K2-1-u2-X14"}],"explanation":["글에 「코에는 당근을」이라고 나와 있어요.","단추는 눈에 붙였고, 솔방울은 나오지 않아요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#2','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":2,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"맴맴","correct":true},{"t":"시원하다","mis":"K2-1-u2-X15"},{"t":"여름날","mis":"K2-1-u2-X15"}],"explanation":["「맴맴」은 매미 소리를 흉내 낸 말이에요.","「시원하다」와 「여름날」은 소리를 흉내 낸 말이 아니에요.","소리 내어 따라 하면 소리가 들리는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"강아지","mis":"K2-1-u2-X15"},{"t":"짖다","mis":"K2-1-u2-X15"}],"explanation":["「멍멍」은 강아지가 짖는 소리를 흉내 낸 말이에요.","「강아지」는 동물 이름, 「짖다」는 하는 일이에요.","소리 내어 따라 하면 소리가 들리는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#3','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":3,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u2-X15"},{"t":"빠르다","mis":"K2-1-u2-X15"}],"explanation":["「깡충깡충」은 토끼가 뛰는 모양을 흉내 낸 말이에요.","「토끼」는 동물 이름, 「빠르다」는 흉내 낸 말이 아니에요.","따라 하면 모습이 떠오르는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"공","mis":"K2-1-u2-X15"},{"t":"굴리다","mis":"K2-1-u2-X15"}],"explanation":["「데굴데굴」은 굴러가는 모양을 흉내 낸 말이에요.","「공」은 물건 이름, 「굴리다」는 하는 일이에요.","따라 하면 모습이 떠오르는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#4','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',1,'ox','auto','같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.',ARRAY['K2-1-u2-X16']::text[],true,'{"seq":4,"concept":"K2-1-u2-C9","difficulty":1,"kind":"ox","stem":"같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 생각이 다르니까","correct":true},{"t":"정답인 느낌은 하나뿐이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["읽는 사람마다 떠오르는 경험이 달라요.","그래서 느낌도 다를 수 있어요.","친구의 다른 느낌도 「그럴 수 있구나」 하고 들어요."],"variant_rule":{"alt":[{"stem":"내 느낌을 말할 때는 그렇게 느낀 까닭을 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"왜 그렇게 느꼈는지 친구가 알 수 있으니까","correct":true},{"t":"느낌만 말하면 충분하니까","mis":"K2-1-u2-X16"}],"explanation":["까닭을 말하면 내 느낌이 잘 전해져요.","「재미있었어.」보다 「~해서 재미있었어.」가 좋아요.","어느 장면에서, 왜 그런지 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#5','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'match','auto','흉내 내는 말과 알맞은 것을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C8","difficulty":2,"kind":"match","stem":"흉내 내는 말과 알맞은 것을 이어 보세요.","pairs":[{"l":"꿀꿀","r":"돼지가 우는 소리"},{"l":"째깍째깍","r":"시계가 가는 소리"},{"l":"엉금엉금","r":"거북이가 기어가는 모양"}],"mis":"K2-1-u2-X15","explanation":["「꿀꿀」은 돼지 소리예요.","「째깍째깍」은 시계 소리예요.","「엉금엉금」은 거북이가 느리게 기는 모양이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 흉내 내는 말과 알맞은 것을 이어 보세요.","pairs":[{"l":"개굴개굴","r":"개구리가 우는 소리"},{"l":"주룩주룩","r":"비가 쏟아지는 소리"},{"l":"살금살금","r":"몰래 걷는 모양"}],"explanation":["「개굴개굴」은 개구리 소리예요.","「주룩주룩」은 비가 쏟아지는 소리예요.","「살금살금」은 몰래 걷는 모양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#6','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 빗방울이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],true,'{"seq":6,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 빗방울이 떨어지는 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"후드득","correct":true},{"t":"우르르 쾅쾅","mis":"K2-1-u2-X14"},{"t":"찰랑찰랑","mis":"K2-1-u2-X14"}],"explanation":["「빗방울이 후드득 떨어지기」라고 나와 있어요.","「우르르 쾅쾅」은 하늘, 「찰랑찰랑」은 웅덩이 물이에요.","무엇의 소리인지 글에서 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 눈을 굴리는 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"펑펑","mis":"K2-1-u2-X14"},{"t":"쌩쌩","mis":"K2-1-u2-X14"}],"explanation":["「눈을 데굴데굴 굴려」라고 나와 있어요.","「펑펑」은 눈이 내리는 모양, 「쌩쌩」은 바람이에요.","무엇의 모양인지 글에서 짚어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#7','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'sa','auto','빈칸에 알맞은 흉내 내는 말을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#8','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',2,'mc','auto','「첨벙첨벙 빗길」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u2-X16','K2-1-u2-X14']::text[],true,'{"seq":8,"concept":"K2-1-u2-C9","difficulty":2,"kind":"mc","stem":"「첨벙첨벙 빗길」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「첨벙첨벙 걷는 장면이 재미있었어. 나도 장화 신고 웅덩이를 밟은 적이 있거든.」","correct":true},{"t":"「재미있었어.」","mis":"K2-1-u2-X16"},{"t":"「지우가 비를 맞아서 슬펐어.」","mis":"K2-1-u2-X14"}],"explanation":["장면과 내 경험(까닭)을 함께 말했어요.","까닭 없는 말은 느낌이 잘 전해지지 않아요.","지우는 우산을 썼고 재미있어했어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"},"variant_rule":{"alt":[{"stem":"「데굴데굴 눈사람」을 읽고 느낌을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「눈사람에 단추를 붙이는 장면이 재미있었어. 나도 동생이랑 눈사람을 만들고 싶어.」","correct":true},{"t":"「좋았어.」","mis":"K2-1-u2-X16"},{"t":"「도윤이가 눈사람을 부숴서 속상했어.」","mis":"K2-1-u2-X14"}],"explanation":["장면과 내 바람(까닭)을 함께 말했어요.","까닭 없는 말은 느낌이 잘 전해지지 않아요.","글에서 도윤이는 눈사람을 부수지 않았어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#9','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C8',2,'ox','auto','「쌩쌩」은 바람이 세게 부는 소리를 흉내 낸 말이에요.',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":9,"concept":"K2-1-u2-C8","difficulty":2,"kind":"ox","stem":"「쌩쌩」은 바람이 세게 부는 소리를 흉내 낸 말이에요.","answer":"O","reason_options":[{"t":"바람 소리를 따라 한 말이니까","correct":true},{"t":"바람의 이름이니까","mis":"K2-1-u2-X15"}],"mis":"K2-1-u2-X15","explanation":["「쌩쌩」은 바람이 세게 부는 소리예요.","흉내 내는 말은 이름이 아니라 소리나 모양을 따라 한 말이에요.","따라 하면 바람 소리가 들리는 듯해요."],"variant_rule":{"alt":[{"stem":"「여름날」은 소리를 흉내 낸 말이에요.","answer":"X","reason_options":[{"t":"때를 나타내는 낱말이니까","correct":true},{"t":"여름에 들리는 말이니까","mis":"K2-1-u2-X15"}],"explanation":["「여름날」은 때를 나타내는 낱말이에요.","소리를 흉내 낸 말은 「맴맴」, 「윙윙」 같은 말이에요.","따라 했을 때 소리가 나는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_basic#10','kor',2,1,'u2','L08','g2_1_kor_u2_L08_basic','lesson_basic','K2-1-u2-C9',3,'error','auto','「찰박찰박 시냇가」를 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X14','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C9","difficulty":3,"kind":"error","stem":"「찰박찰박 시냇가」를 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「하준이가 물에 빠져서 무서웠어.」","correct":true,"mis_target":"K2-1-u2-X14"},{"t":"다은 — 「차가운 물에 발을 담그는 장면에서 나도 시원했어.」","mis":"K2-1-u2-X19"},{"t":"시우 — 「물고기가 발가락 사이로 지나갈 때 간지러울 것 같았어.」","mis":"K2-1-u2-X19"}],"explanation":["하준이가 물에 빠졌다는 이야기는 글에 없어요.","다은이와 시우는 글의 장면을 들어 느낌을 말했어요.","느낌도 글에 나온 장면에서 출발해요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"},"variant_rule":{"alt":[{"stem":"「데굴데굴 눈사람」을 읽고 느낌을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 「두 볼이 꽁꽁 얼어서 슬펐을 것 같아.」","correct":true,"mis_target":"K2-1-u2-X16"},{"t":"하린 — 「눈을 굴리는 장면이 신나 보였어.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「단추를 붙이는 장면에서 웃음이 났어.」","mis":"K2-1-u2-X19"}],"explanation":["글에는 두 볼이 따끈따끈했다고 나와 있어요.","태민이는 글과 반대로 짐작했어요.","하린이와 지안이는 글의 장면을 들어 느낌을 말했어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#1','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 부침개를 부칠 때 난 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":1,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 부침개를 부칠 때 난 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"지글지글","correct":true},{"t":"호호","mis":"K2-1-u2-X14"},{"t":"후드득","mis":"K2-1-u2-X14"}],"explanation":["「팬에서 지글지글 소리가 났어요」라고 나와 있어요.","「호호」는 서아가 부는 소리이고, 「후드득」은 글에 없어요.","무엇의 소리인지 글에서 짚어요."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#2','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',2,'mc','auto','글을 읽고 답해 보세요. 서아가 빗소리와 부침개 소리가 똑같다고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":2,"concept":"K2-1-u2-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서아가 빗소리와 부침개 소리가 똑같다고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지글지글 소리가 빗소리처럼 들려서","correct":true},{"t":"부침개가 비에 젖어서","mis":"K2-1-u2-X14"},{"t":"아빠가 비를 좋아하셔서","mis":"K2-1-u2-X14"}],"explanation":["부침개 부치는 소리가 빗소리와 비슷하게 들렸어요.","부침개가 젖었다거나 아빠가 비를 좋아한다는 말은 글에 없어요.","글 속 소리를 떠올려 까닭을 찾아요."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#3','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":3,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"쏙쏙","correct":true},{"t":"깔깔","mis":"K2-1-u2-X15"},{"t":"찰박찰박","mis":"K2-1-u2-X15"}],"explanation":["「쏙쏙」은 물고기가 빠르게 지나가는 모양이에요.","「깔깔」은 웃음소리, 「찰박찰박」은 물을 차는 소리예요.","소리인지 모양인지 따라 해 보며 가려요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#4','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":4,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"비 오는 날이 즐거워요","correct":true},{"t":"천둥이 무서워 울고 싶어요","mis":"K2-1-u2-X16"},{"t":"비가 와서 심심해요","mis":"K2-1-u2-X16"}],"explanation":["지우는 「비 오는 날도 참 재미있다!」라고 말했어요.","첨벙첨벙 걷는 모습에서도 즐거움이 느껴져요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#5','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'ox','auto','흉내 내는 말을 넣으면 글이 더 생생하게 느껴져요.',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":5,"concept":"K2-1-u2-C8","difficulty":3,"kind":"ox","stem":"흉내 내는 말을 넣으면 글이 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"소리와 모습이 눈앞에 그려지니까","correct":true},{"t":"글자 수가 늘어나니까","mis":"K2-1-u2-X15"}],"mis":"K2-1-u2-X15","explanation":["「눈이 내렸어요.」보다 「눈이 펑펑 내렸어요.」가 생생해요.","글이 길어져서가 아니라 모습이 떠올라서 좋아요.","흉내 내는 말을 찾으며 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#6','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',3,'error','auto','흉내 내는 말을 넣어 문장을 만들었어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u2-X15','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C8","difficulty":3,"kind":"error","stem":"흉내 내는 말을 넣어 문장을 만들었어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"서아 — 「고양이가 꿀꿀 울어요.」","correct":true,"mis_target":"K2-1-u2-X15"},{"t":"준우 — 「병아리가 삐악삐악 울어요.」","mis":"K2-1-u2-X19"},{"t":"하린 — 「거북이가 엉금엉금 기어가요.」","mis":"K2-1-u2-X19"}],"explanation":["「꿀꿀」은 돼지 소리예요.","고양이 소리는 「야옹」이에요.","준우와 하린이는 알맞게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#7','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 「두 볼은 따끈따끈했어요」에서 짐작할 수 있는 도윤이의 마음은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":7,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「두 볼은 따끈따끈했어요」에서 짐작할 수 있는 도윤이의 마음은 어느 것인가요?","options":[{"t":"신나게 놀아서 즐거워요","correct":true},{"t":"추워서 집에 가고 싶어요","mis":"K2-1-u2-X16"},{"t":"동생에게 화가 났어요","mis":"K2-1-u2-X16"}],"explanation":["찬 바람에도 볼이 따끈할 만큼 신나게 놀았어요.","춥다거나 화가 났다는 말은 글에 없어요.","글의 표현에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#8','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'mc','auto','「데굴데굴 눈사람」을 읽고 두 친구가 느낌을 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#9','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C9',4,'essay','teacher','「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.」 — 나도 비 오는 날 장화를 신고 웅덩이를 밟으며 놀았던 일이 떠올라서 재미있었어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L08_challenge#10','kor',2,1,'u2','L08','g2_1_kor_u2_L08_challenge','lesson_challenge','K2-1-u2-C8',4,'essay','teacher','흉내 내는 말을 두 개 넣어 비 오는 날이나 놀이터의 모습을 두 문장으로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C8","difficulty":4,"kind":"essay","stem":"흉내 내는 말을 두 개 넣어 비 오는 날이나 놀이터의 모습을 두 문장으로 써 보세요.","answer_guide":{"answer":"예: 빗방울이 창문에 톡톡 부딪혀요. / 우산을 쓴 친구들이 첨벙첨벙 뛰어가요.","scoring_points":["흉내 내는 말을 두 개 넣었는가","흉내 내는 말이 그 장면에 어울리는가","두 문장을 썼는가"]},"explanation":["흉내 내는 말 둘.","장면에 어울림.","두 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#1','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":1,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"책의 값","mis":"K2-1-u2-X17"},{"t":"책을 산 날짜","mis":"K2-1-u2-X17"}],"explanation":["제목을 알아야 친구가 그 책을 찾아 읽을 수 있어요.","값이나 산 날짜는 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"내가 좋아하는 문장","correct":true},{"t":"책의 쪽수","mis":"K2-1-u2-X17"},{"t":"책의 무게","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 문장을 말하면 책의 맛이 전해져요.","쪽수나 무게는 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#2','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책갈피에 적기 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X09']::text[],true,'{"seq":2,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"마음에 드는 문장 한 줄","correct":true},{"t":"책 한 쪽을 통째로","mis":"K2-1-u2-X17"},{"t":"친구를 흉보는 말","mis":"K2-1-u2-X09"}],"explanation":["책갈피에는 마음에 쏙 든 짧은 문장이 어울려요.","책을 통째로 옮기면 너무 길고, 흉보는 말은 쓰지 않아요.","짧은 문장 한 줄을 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"힘이 나는 짧은 문장","correct":true},{"t":"책 첫 장부터 끝 장까지","mis":"K2-1-u2-X17"},{"t":"짝꿍 놀리는 별명","mis":"K2-1-u2-X09"}],"explanation":["책갈피에는 마음에 드는 짧은 문장이 어울려요.","책을 통째로 옮기거나 놀리는 말을 쓰면 안 돼요.","짧은 문장 한 줄을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#3','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'mc','auto','책갈피는 무엇인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":3,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피는 무엇인가요?","options":[{"t":"읽던 곳을 표시해 두는 작은 종이","correct":true},{"t":"책의 겉을 싸는 종이","mis":"K2-1-u2-X17"},{"t":"책을 담는 가방","mis":"K2-1-u2-X17"}],"explanation":["책갈피는 읽던 곳에 끼워 표시해요.","책을 싸는 종이나 가방은 책갈피가 아니에요.","좋아하는 문장을 적으면 나만의 책갈피가 돼요."],"variant_rule":{"alt":[{"stem":"책갈피를 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽던 곳을 쉽게 다시 찾으려고","correct":true},{"t":"책을 빨리 다 읽으려고","mis":"K2-1-u2-X17"},{"t":"책값을 적어 두려고","mis":"K2-1-u2-X17"}],"explanation":["책갈피를 끼워 두면 읽던 곳을 쉽게 찾아요.","빨리 읽거나 값을 적으려고 쓰는 것이 아니에요.","좋아하는 문장을 적어 두면 더 좋아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#4','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',1,'ox','auto','좋아하는 문장을 소개할 때 좋아하는 까닭을 함께 말하면 좋아요.',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":4,"concept":"K2-1-u2-C10","difficulty":1,"kind":"ox","stem":"좋아하는 문장을 소개할 때 좋아하는 까닭을 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"친구가 내 마음을 알고 책을 읽고 싶어지니까","correct":true},{"t":"문장만 말하면 충분하니까","mis":"K2-1-u2-X17"}],"mis":"K2-1-u2-X17","explanation":["까닭을 들으면 친구도 그 문장이 좋아질 수 있어요.","문장만 말하면 왜 좋은지 알기 어려워요.","「~해서 좋아요.」 하고 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 책 제목은 말하지 않아도 돼요.","answer":"X","reason_options":[{"t":"제목을 알아야 친구가 그 책을 찾아 읽을 수 있으니까","correct":true},{"t":"좋아하는 문장만 좋으면 되니까","mis":"K2-1-u2-X17"}],"explanation":["제목을 모르면 친구가 그 책을 찾을 수 없어요.","소개할 때 제목을 먼저 말해요.","제목 → 좋아하는 문장 → 까닭 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#5','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'match','auto','책 소개의 부분과 알맞은 말을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C10","difficulty":2,"kind":"match","stem":"책 소개의 부분과 알맞은 말을 이어 보세요.","pairs":[{"l":"책 제목","r":"「제가 좋아하는 책은 『달팽이 우체부』예요.」"},{"l":"좋아하는 문장","r":"「좋아하는 문장은 ‘느려도 꼭 도착할 거야.’예요.」"},{"l":"까닭","r":"「포기하지 않는 마음이 멋져서 좋아요.」"}],"mis":"K2-1-u2-X17","explanation":["먼저 책 제목을 말해요.","다음에 좋아하는 문장을 말해요.","마지막으로 좋아하는 까닭을 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 책 소개의 부분과 알맞은 말을 이어 보세요.","pairs":[{"l":"책 제목","r":"「제가 좋아하는 책은 『겁쟁이 고양이 뭉치』예요.」"},{"l":"좋아하는 문장","r":"「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요.」"},{"l":"까닭","r":"「읽으면 마음이 편해져서 좋아요.」"}],"explanation":["먼저 책 제목을 말해요.","다음에 좋아하는 문장을 말해요.","마지막으로 좋아하는 까닭을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#6','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'mc','auto','책을 소개하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":6,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책을 소개하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"책 제목 → 좋아하는 문장 → 좋아하는 까닭","correct":true},{"t":"좋아하는 까닭 → 책 제목 → 좋아하는 문장","mis":"K2-1-u2-X17"},{"t":"좋아하는 문장 → 좋아하는 까닭 (제목은 빼요)","mis":"K2-1-u2-X17"}],"explanation":["제목을 먼저 말해야 어떤 책인지 알아요.","그다음 문장과 까닭을 말하면 깔끔해요.","제목을 빼면 친구가 책을 찾을 수 없어요."],"variant_rule":{"alt":[{"stem":"책을 소개할 때 가장 먼저 말하면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"좋아하는 까닭","mis":"K2-1-u2-X17"},{"t":"책을 다 읽은 날짜","mis":"K2-1-u2-X17"}],"explanation":["제목을 먼저 말해야 어떤 책인지 알아요.","까닭은 좋아하는 문장 다음에 말해요.","읽은 날짜는 꼭 말하지 않아도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#7','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'sa','auto','읽던 곳에 끼워 표시해 두는 작은 종이를 무엇이라고 하나요?','{}'::text[],true,'{"seq":7,"concept":"K2-1-u2-C10","difficulty":2,"kind":"sa","stem":"읽던 곳에 끼워 표시해 두는 작은 종이를 무엇이라고 하나요?","answer":["책갈피"],"explanation":["읽던 곳을 표시하는 종이는 책갈피예요.","좋아하는 문장을 적어 꾸밀 수 있어요.","나만의 책갈피를 만들어 봐요."],"variant_rule":{"alt":[{"stem":"책의 이름을 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["제목"],"explanation":["책의 이름은 「제목」이에요.","책을 소개할 때 제목을 먼저 말해요.","제목을 알아야 그 책을 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#8','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'mc','auto','책 소개로 가장 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개로 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「이 문장을 읽으면 힘이 나서 좋아요.」","correct":true},{"t":"「그냥 아무거나요.」","mis":"K2-1-u2-X17"},{"t":"「책 이름은 몰라요.」","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 까닭을 함께 말했어요.","「아무거나」나 「몰라요」로는 책이 소개되지 않아요.","제목, 문장, 까닭을 담아 말해요."],"variant_rule":{"alt":[{"stem":"친구의 책 소개를 듣고 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 문장 나도 마음에 들어. 나도 읽어 볼래.」","correct":true},{"t":"「그 책 재미없어.」","mis":"K2-1-u2-X09"},{"t":"(친구가 말하는 중에) 「내 책이 더 좋아!」","mis":"K2-1-u2-X08"}],"explanation":["친구 소개에서 좋은 점을 찾아 말해요.","깎아내리거나 끼어들면 친구가 속상해요.","끝까지 듣고 마음에 든 점을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#9','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',2,'ox','auto','책갈피에는 책 한 쪽을 통째로 옮겨 써요.',ARRAY['K2-1-u2-X17']::text[],true,'{"seq":9,"concept":"K2-1-u2-C10","difficulty":2,"kind":"ox","stem":"책갈피에는 책 한 쪽을 통째로 옮겨 써요.","answer":"X","reason_options":[{"t":"마음에 드는 짧은 문장 한 줄이 알맞으니까","correct":true},{"t":"많이 쓸수록 좋으니까","mis":"K2-1-u2-X17"}],"mis":"K2-1-u2-X17","explanation":["책갈피는 작아서 짧은 문장이 어울려요.","마음에 쏙 든 한 줄을 골라요.","고른 까닭도 생각해 두어요."],"variant_rule":{"alt":[{"stem":"좋아하는 문장은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"마음에 와닿는 문장이 저마다 다르니까","correct":true},{"t":"정답인 문장이 하나 정해져 있으니까","mis":"K2-1-u2-X16"}],"explanation":["같은 책을 읽어도 좋아하는 문장은 다를 수 있어요.","친구가 고른 문장도 소중해요.","왜 그 문장을 골랐는지 물어봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_basic#10','kor',2,1,'u2','L10','g2_1_kor_u2_L10_basic','lesson_basic','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"예린 — 「제 책은… 제목은 몰라요. 그냥 재미있어요.」","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"하준 — 「제가 좋아하는 책은 『작은 씨앗의 여행』이에요. 씨앗이 용감해서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요. 마음이 편해져서 좋아요.」","mis":"K2-1-u2-X19"}],"explanation":["예린이는 제목도, 좋아하는 문장도, 까닭도 말하지 않았어요.","하준이와 지안이는 제목이나 문장과 까닭을 말했어요.","제목 → 문장 → 까닭을 담아 소개해요."],"variant_rule":{"alt":[{"stem":"친구들이 책갈피를 보여 주며 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"현우 — 책 세 쪽을 그대로 옮겨 적은 책갈피를 보여 주었어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"소율 — 「힘내, 너는 할 수 있어.」 한 줄을 적었어요","mis":"K2-1-u2-X19"},{"t":"서아 — 좋아하는 문장 한 줄과 작은 그림을 그렸어요","mis":"K2-1-u2-X19"}],"explanation":["책 세 쪽을 옮기면 책갈피에 너무 길어요.","책갈피에는 마음에 드는 짧은 문장 한 줄이 알맞아요.","소율이와 서아는 알맞게 만들었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#1','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',2,'mc','auto','책 소개를 읽고 답해 보세요. 도윤이가 좋아하는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":1,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개를 읽고 답해 보세요. 도윤이가 좋아하는 문장은 어느 것인가요?","options":[{"t":"느려도 꼭 도착할 거야.","correct":true},{"t":"달팽이 우체부","mis":"K2-1-u2-X17"},{"t":"포기하지 않는 달팽이의 마음이 멋져요.","mis":"K2-1-u2-X17"}],"explanation":["「좋아하는 문장은 ~예요.」에 나와 있어요.","『달팽이 우체부』는 제목, 마지막 줄은 까닭이에요.","제목, 문장, 까닭을 가려 읽어요."],"asset":{"type":"passage","lines":["제가 좋아하는 책은 『달팽이 우체부』예요.","좋아하는 문장은 「느려도 꼭 도착할 거야.」예요.","포기하지 않는 달팽이의 마음이 멋져서 좋아요."],"title":"도윤이의 책 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#2','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',2,'mc','auto','책 소개를 읽고 답해 보세요. 도윤이가 그 문장을 좋아하는 까닭은 무엇인가요?',ARRAY['K2-1-u2-X14','K2-1-u2-X17']::text[],false,'{"seq":2,"concept":"K2-1-u2-C10","difficulty":2,"kind":"mc","stem":"책 소개를 읽고 답해 보세요. 도윤이가 그 문장을 좋아하는 까닭은 무엇인가요?","options":[{"t":"포기하지 않는 달팽이의 마음이 멋져서","correct":true},{"t":"달팽이가 빨리 달려서","mis":"K2-1-u2-X14"},{"t":"책이 얇아서","mis":"K2-1-u2-X17"}],"explanation":["마지막 줄에 까닭이 나와 있어요.","달팽이가 빨리 달린다는 말은 글에 없어요.","까닭은 「~해서 좋아요」 부분에서 찾아요."],"asset":{"type":"passage","lines":["제가 좋아하는 책은 『달팽이 우체부』예요.","좋아하는 문장은 「느려도 꼭 도착할 거야.」예요.","포기하지 않는 달팽이의 마음이 멋져서 좋아요."],"title":"도윤이의 책 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#3','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','친구들이 만든 책갈피예요. 가장 알맞게 만든 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X09']::text[],false,'{"seq":3,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"친구들이 만든 책갈피예요. 가장 알맞게 만든 것은 어느 것인가요?","options":[{"t":"『겁쟁이 고양이 뭉치』 — 천천히 해도 괜찮아.","correct":true},{"t":"책 1쪽부터 5쪽까지를 그대로 옮겨 적은 책갈피","mis":"K2-1-u2-X17"},{"t":"「짝꿍 바보」라고 적은 책갈피","mis":"K2-1-u2-X09"}],"explanation":["책 제목과 마음에 드는 문장 한 줄을 적었어요.","책을 통째로 옮기면 너무 길어요.","친구를 놀리는 말은 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#4','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','좋아하는 문장과 까닭이 잘 어울리게 소개한 것은 어느 것인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X14']::text[],false,'{"seq":4,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"좋아하는 문장과 까닭이 잘 어울리게 소개한 것은 어느 것인가요?","options":[{"t":"「나는 할 수 있어!」 — 읽으면 힘이 나는 말이라서 좋아요","correct":true},{"t":"「나는 할 수 있어!」 — 책 표지가 초록색이라서 좋아요","mis":"K2-1-u2-X17"},{"t":"「천천히 해도 괜찮아.」 — 빨리빨리 하라는 말이라서 좋아요","mis":"K2-1-u2-X14"}],"explanation":["힘이 나는 문장에 힘이 난다는 까닭이 어울려요.","표지 색은 문장을 좋아하는 까닭이 아니에요.","「천천히 해도 괜찮아.」는 빨리하라는 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#5','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'ox','auto','친구가 소개한 문장이 내 마음에 들지 않으면 「그 문장은 별로야.」 하고 말해요.',ARRAY['K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C10","difficulty":3,"kind":"ox","stem":"친구가 소개한 문장이 내 마음에 들지 않으면 「그 문장은 별로야.」 하고 말해요.","answer":"X","reason_options":[{"t":"친구가 고른 까닭을 듣고 좋은 점을 찾아 말하는 것이 좋으니까","correct":true},{"t":"솔직하게 깎아내려야 하니까","mis":"K2-1-u2-X09"}],"mis":"K2-1-u2-X09","explanation":["좋아하는 문장은 사람마다 달라요.","깎아내리면 친구가 속상해요.","「왜 그 문장이 좋아?」 하고 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#6','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'error','auto','친구들이 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"태민 — 「재밌어요.」라고만 말하고 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"은솔 — 제목, 좋아하는 문장, 까닭을 차례로 말했어요","mis":"K2-1-u2-X19"},{"t":"하람 — 친구들을 보며 좋아하는 문장을 또박또박 읽었어요","mis":"K2-1-u2-X19"}],"explanation":["태민이는 제목도 문장도 까닭도 말하지 않았어요.","은솔이와 하람이는 알맞게 소개했어요.","제목 → 문장 → 까닭을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#7','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',3,'mc','auto','친구가 책을 설명했어요. 「겁 많은 토끼가 용기를 내어 모험을 떠나는 책이에요. 좋아하는 문장은 ‘나는 할 수 있어!’예요.」 어울리는 제목은 어느 것인가요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":7,"concept":"K2-1-u2-C10","difficulty":3,"kind":"mc","stem":"친구가 책을 설명했어요. 「겁 많은 토끼가 용기를 내어 모험을 떠나는 책이에요. 좋아하는 문장은 ‘나는 할 수 있어!’예요.」 어울리는 제목은 어느 것인가요?","options":[{"t":"『용감한 토끼』","correct":true},{"t":"『겁쟁이 고양이 뭉치』","mis":"K2-1-u2-X14"},{"t":"『달팽이 우체부』","mis":"K2-1-u2-X14"}],"explanation":["토끼가 용기를 내는 책이니 『용감한 토끼』가 어울려요.","고양이나 달팽이는 설명에 나오지 않아요.","설명 속 인물과 일을 짚어 제목을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#8','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#9','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'essay','teacher','좋아하는 책 한 권을 소개하는 말을 세 문장으로 써 보세요. 제목, 좋아하는 문장, 좋아하는 까닭을 차례로 담아요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"좋아하는 책 한 권을 소개하는 말을 세 문장으로 써 보세요. 제목, 좋아하는 문장, 좋아하는 까닭을 차례로 담아요.","answer_guide":{"answer":"예: 제가 좋아하는 책은 『달팽이 우체부』예요. / 좋아하는 문장은 「느려도 꼭 도착할 거야.」예요. / 포기하지 않는 마음이 멋져서 좋아요.","scoring_points":["책 제목을 썼는가","좋아하는 문장을 썼는가","좋아하는 까닭을 썼는가"]},"explanation":["제목.","좋아하는 문장.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L10_challenge#10','kor',2,1,'u2','L10','g2_1_kor_u2_L10_challenge','lesson_challenge','K2-1-u2-C10',4,'essay','teacher','내가 책갈피를 만든다면 어떤 문장을 적고 싶은지 쓰고, 그 문장을 고른 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C10","difficulty":4,"kind":"essay","stem":"내가 책갈피를 만든다면 어떤 문장을 적고 싶은지 쓰고, 그 문장을 고른 까닭을 써 보세요.","answer_guide":{"answer":"예: 「천천히 해도 괜찮아.」 — 급해서 속상할 때 보면 마음이 편해질 것 같아서 골랐어요.","scoring_points":["책갈피에 적을 짧은 문장을 썼는가","그 문장을 고른 까닭을 썼는가","까닭이 문장의 뜻과 어울리는가"]},"explanation":["짧은 문장.","고른 까닭.","뜻과 어울림."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#1','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'mc','auto','떡볶이 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":1,"concept":"K2-1-u2-C11","difficulty":1,"kind":"mc","stem":"떡볶이 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"매콤달콤 떡볶이","correct":true},{"t":"가게1호","mis":"K2-1-u2-X18"},{"t":"음식 파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「매콤달콤」은 떡볶이 맛이 떠오르는 재미있는 말이에요.","「가게1호」, 「음식 파는 곳」은 무엇을 파는지도 재미도 드러나지 않아요.","맛이나 모양을 살려 이름을 지어요."],"variant_rule":{"alt":[{"stem":"국숫집에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"후루룩 국수","correct":true},{"t":"가게 2번","mis":"K2-1-u2-X18"},{"t":"밥 먹는 집","mis":"K2-1-u2-X18"}],"explanation":["「후루룩」은 국수 먹는 소리가 떠오르는 말이에요.","「가게 2번」, 「밥 먹는 집」은 국숫집인지 알기 어려워요.","소리 흉내 말을 넣으면 이름이 재미있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#2','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'mc','auto','소리를 흉내 낸 말을 넣어 지은 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":2,"concept":"K2-1-u2-C11","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말을 넣어 지은 이름은 어느 것인가요?","options":[{"t":"보글보글 찌개집","correct":true},{"t":"맛있는 찌개집","mis":"K2-1-u2-X18"},{"t":"큰 찌개집","mis":"K2-1-u2-X18"}],"explanation":["「보글보글」은 찌개가 끓는 소리예요.","「맛있는」, 「큰」은 소리를 흉내 낸 말이 아니에요.","소리 흉내 말을 넣으면 이름이 통통 튀어요."],"variant_rule":{"alt":[{"stem":"같은 소리를 되풀이해 지은 이름은 어느 것인가요?","options":[{"t":"콩콩 두부집","correct":true},{"t":"두부 파는 집","mis":"K2-1-u2-X18"},{"t":"하얀 두부집","mis":"K2-1-u2-X18"}],"explanation":["「콩콩」은 같은 소리를 되풀이했어요.","되풀이하면 리듬이 생겨 기억에 잘 남아요.","다른 두 이름에는 되풀이한 소리가 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#3','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C5',1,'mc','auto','이름 짓기 놀이를 할 때 지킬 약속은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],true,'{"seq":3,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"이름 짓기 놀이를 할 때 지킬 약속은 어느 것인가요?","options":[{"t":"친구를 놀리는 말은 쓰지 않아요","correct":true},{"t":"친구 이름을 바꿔 놀리는 이름을 지어요","mis":"K2-1-u2-X09"},{"t":"내 생각대로만 정해요","mis":"K2-1-u2-X08"}],"explanation":["놀리는 말은 친구를 속상하게 해요.","혼자 정하면 함께 즐길 수 없어요.","모두가 즐거운 이름을 지어요."],"variant_rule":{"alt":[{"stem":"모둠에서 함께 이름 짓기 활동을 정할 때 알맞은 것은 어느 것인가요?","options":[{"t":"모두의 생각을 모아요","correct":true},{"t":"목소리 큰 친구 생각대로 해요","mis":"K2-1-u2-X08"},{"t":"싫은 생각에는 「그건 바보 같아.」 하고 말해요","mis":"K2-1-u2-X09"}],"explanation":["모두의 생각을 모으면 더 재미있는 생각이 나와요.","한 사람이 정하거나 깎아내리면 함께 즐길 수 없어요.","친구 생각을 끝까지 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#4','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',1,'ox','auto','음식의 특징을 살려 이름을 지으면 무엇을 파는지 알기 쉬워요.',ARRAY['K2-1-u2-X18']::text[],true,'{"seq":4,"concept":"K2-1-u2-C11","difficulty":1,"kind":"ox","stem":"음식의 특징을 살려 이름을 지으면 무엇을 파는지 알기 쉬워요.","answer":"O","reason_options":[{"t":"이름만 들어도 맛이나 모양이 떠오르니까","correct":true},{"t":"이름은 짧을수록 좋으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「뜨끈한 국수집」처럼 특징을 살리면 무엇을 파는지 알아요.","짧기만 한 이름은 무엇인지 알기 어려워요.","특징을 살리고 소리의 재미를 더해요."],"variant_rule":{"alt":[{"stem":"「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"무엇을 파는지도, 소리의 재미도 없으니까","correct":true},{"t":"숫자가 들어가 기억하기 쉬우니까","mis":"K2-1-u2-X18"}],"explanation":["「가게1호」만 들어서는 무엇을 파는지 몰라요.","소리의 재미도 느껴지지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#5','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'match','auto','가게와 어울리는 재미있는 이름을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u2-C11","difficulty":2,"kind":"match","stem":"가게와 어울리는 재미있는 이름을 이어 보세요.","pairs":[{"l":"빵집","r":"폭신폭신 빵집"},{"l":"김밥집","r":"돌돌 말이 김밥"},{"l":"튀김집","r":"바삭바삭 튀김"}],"mis":"K2-1-u2-X18","explanation":["「폭신폭신」은 부드러운 빵이 떠올라요.","「돌돌」은 김밥을 마는 모양이에요.","「바삭바삭」은 튀김 씹는 소리예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 가게와 어울리는 재미있는 이름을 이어 보세요.","pairs":[{"l":"과일 가게","r":"새콤달콤 과일"},{"l":"꽃집","r":"방긋방긋 꽃집"},{"l":"신발 가게","r":"폴짝폴짝 신발"}],"explanation":["「새콤달콤」은 과일 맛이 떠올라요.","「방긋방긋」은 웃는 꽃이 떠올라요.","「폴짝폴짝」은 신발 신고 뛰는 모습이 떠올라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#6','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'mc','auto','「지글지글 고기집」에서 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],true,'{"seq":6,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「지글지글 고기집」에서 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"지글지글","correct":true},{"t":"고기","mis":"K2-1-u2-X15"},{"t":"집","mis":"K2-1-u2-X15"}],"explanation":["「지글지글」은 고기 굽는 소리예요.","「고기」, 「집」은 이름에 들어간 낱말이지만 흉내 내는 말은 아니에요.","소리 내어 따라 하면 소리가 들리는지 봐요."],"variant_rule":{"alt":[{"stem":"「바삭바삭 튀김」에서 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"바삭바삭","correct":true},{"t":"튀김","mis":"K2-1-u2-X15"},{"t":"튀기다","mis":"K2-1-u2-X15"}],"explanation":["「바삭바삭」은 튀김을 씹는 소리예요.","「튀김」은 음식 이름, 「튀기다」는 하는 일이에요.","소리 내어 따라 하면 소리가 들리는지 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#7','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'sa','auto','국수를 먹는 소리를 흉내 낸 말을 넣어 이름을 완성해 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#8','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',2,'mc','auto','재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X09']::text[],true,'{"seq":8,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 소리를 되풀이해 리듬을 살려요","correct":true},{"t":"아무 글자나 막 붙여요","mis":"K2-1-u2-X18"},{"t":"친구 별명을 놀리듯 넣어요","mis":"K2-1-u2-X09"}],"explanation":["「콩콩」, 「폴짝폴짝」처럼 되풀이하면 리듬이 생겨요.","아무 글자나 붙이면 뜻도 재미도 없어요.","친구를 놀리는 말은 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 재미있는 이름을 짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식의 맛이나 모양을 살려요","correct":true},{"t":"숫자만 붙여요","mis":"K2-1-u2-X18"},{"t":"친구가 싫어하는 별명을 넣어요","mis":"K2-1-u2-X09"}],"explanation":["「매콤달콤 떡볶이」처럼 특징을 살려요.","숫자만 붙이면 무엇인지 알 수 없어요.","친구를 놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#9','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C5',2,'ox','auto','친구가 지은 이름이 우스우면 「이상해!」 하고 놀려도 돼요.',ARRAY['K2-1-u2-X09']::text[],true,'{"seq":9,"concept":"K2-1-u2-C5","difficulty":2,"kind":"ox","stem":"친구가 지은 이름이 우스우면 「이상해!」 하고 놀려도 돼요.","answer":"X","reason_options":[{"t":"친구 마음이 상하고 함께 즐길 수 없으니까","correct":true},{"t":"솔직하게 말하는 것이니까","mis":"K2-1-u2-X09"}],"mis":"K2-1-u2-X09","explanation":["놀리면 친구가 다시 생각을 말하고 싶지 않아져요.","좋은 점을 먼저 찾아 말해요.","「거기에 흉내 내는 말을 붙여 볼까?」 하고 도와요."],"variant_rule":{"alt":[{"stem":"친구 이름을 바꿔 부르며 놀리는 것도 재미있는 말놀이예요.","answer":"X","reason_options":[{"t":"놀리는 말은 친구를 속상하게 하니까","correct":true},{"t":"다 같이 웃으니까","mis":"K2-1-u2-X09"}],"explanation":["말놀이는 모두가 즐거워야 해요.","한 친구가 속상하면 즐거운 놀이가 아니에요.","놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_basic#10','kor',2,1,'u2','L12','g2_1_kor_u2_L12_basic','lesson_basic','K2-1-u2-C11',3,'error','auto','아이스크림 가게 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X19']::text[],true,'{"seq":10,"concept":"K2-1-u2-C11","difficulty":3,"kind":"error","stem":"아이스크림 가게 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"도담 — 「가게 3번」","correct":true,"mis_target":"K2-1-u2-X18"},{"t":"서윤 — 「시원달콤 아이스」","mis":"K2-1-u2-X19"},{"t":"하늘 — 「사르르 녹는 아이스크림」","mis":"K2-1-u2-X19"}],"explanation":["「가게 3번」은 무엇을 파는지도, 재미도 드러나지 않아요.","서윤이와 하늘이는 맛과 모양을 살려 지었어요.","특징과 흉내 내는 말을 살려요."],"variant_rule":{"alt":[{"stem":"빵집 이름을 지었어요. 알맞지 않게 지은 친구는 누구인가요?","options":[{"t":"지후 — 「먹보 민호네 빵집」","correct":true,"mis_target":"K2-1-u2-X09"},{"t":"아린 — 「몽실몽실 구름빵」","mis":"K2-1-u2-X19"},{"t":"준우 — 「고소고소 소보로」","mis":"K2-1-u2-X19"}],"explanation":["「먹보 민호」는 친구를 놀리는 말이에요.","아린이와 준우는 빵의 모양과 맛을 살려 지었어요.","친구를 놀리는 말은 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#1','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',2,'mc','auto','「폭신폭신 구름빵」에서 「폭신폭신」은 무엇을 살린 말인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":1,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「폭신폭신 구름빵」에서 「폭신폭신」은 무엇을 살린 말인가요?","options":[{"t":"빵이 부드러운 모양","correct":true},{"t":"빵의 값","mis":"K2-1-u2-X18"},{"t":"가게 주인의 이름","mis":"K2-1-u2-X18"}],"explanation":["「폭신폭신」은 부드럽고 푹신한 모양을 흉내 낸 말이에요.","값이나 주인 이름은 드러나지 않아요.","특징을 살린 흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#2','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',2,'mc','auto','「냠냠 김밥」과 「김밥집」 가운데 더 재미있는 이름과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":2,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"「냠냠 김밥」과 「김밥집」 가운데 더 재미있는 이름과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「냠냠 김밥」 — 먹는 소리를 흉내 내어 재미있어서","correct":true},{"t":"「김밥집」 — 짧아서","mis":"K2-1-u2-X18"},{"t":"둘 다 똑같이 재미있어요","mis":"K2-1-u2-X18"}],"explanation":["「냠냠」은 맛있게 먹는 소리예요.","「김밥집」은 무엇을 파는지는 알지만 재미는 없어요.","소리 흉내 말을 넣으면 이름이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#3','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','붕어빵 가게의 특징을 살린 이름으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":3,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"붕어빵 가게의 특징을 살린 이름으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바삭 말랑 붕어빵","correct":true},{"t":"붕어 낚시터","mis":"K2-1-u2-X18"},{"t":"빵빵빵빵","mis":"K2-1-u2-X18"}],"explanation":["겉은 바삭, 속은 말랑한 붕어빵의 특징을 살렸어요.","「붕어 낚시터」는 빵 가게가 아니고, 「빵빵빵빵」은 무엇인지 알 수 없어요.","무엇을 파는지와 특징이 함께 드러나게 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#4','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','수박 주스 가게 이름으로 같은 소리를 되풀이하면서 특징도 살린 것은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":4,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"수박 주스 가게 이름으로 같은 소리를 되풀이하면서 특징도 살린 것은 어느 것인가요?","options":[{"t":"시원시원 수박 주스","correct":true},{"t":"주스 주스 가게","mis":"K2-1-u2-X18"},{"t":"수박 1번","mis":"K2-1-u2-X18"}],"explanation":["「시원시원」은 되풀이한 소리이고 시원한 맛도 살렸어요.","「주스 주스」는 특징이 없고, 「수박 1번」은 재미가 없어요.","되풀이와 특징을 함께 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#5','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'ox','auto','「또르르 굴러온 눈사람 빙수」처럼 흉내 내는 말을 넣으면 이름이 기억에 더 잘 남아요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":5,"concept":"K2-1-u2-C11","difficulty":3,"kind":"ox","stem":"「또르르 굴러온 눈사람 빙수」처럼 흉내 내는 말을 넣으면 이름이 기억에 더 잘 남아요.","answer":"O","reason_options":[{"t":"소리와 모양이 떠올라 재미있으니까","correct":true},{"t":"이름은 길기만 하면 좋으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["흉내 내는 말은 모습을 떠올리게 해요.","길다고 좋은 이름은 아니에요.","특징과 재미가 담겨야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#6','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C5',3,'error','auto','모둠에서 이름을 정하고 있어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X19']::text[],false,'{"seq":6,"concept":"K2-1-u2-C5","difficulty":3,"kind":"error","stem":"모둠에서 이름을 정하고 있어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"현우 — 「내가 정한 이름으로 해! 다른 건 안 돼.」","correct":true,"mis_target":"K2-1-u2-X08"},{"t":"아린 — 「다 같이 생각을 하나씩 말해 보자.」","mis":"K2-1-u2-X19"},{"t":"소율 — 「그 이름 재미있다. 흉내 내는 말을 붙여 볼까?」","mis":"K2-1-u2-X19"}],"explanation":["현우는 혼자 정하고 다른 생각을 막았어요.","아린이와 소율이는 함께 정하려고 했어요.","모두의 생각을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#7','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',3,'mc','auto','떡집 주인이 말했어요. 「우리 떡은 쫀득쫀득하고 색깔이 알록달록해요.」 이 떡집에 어울리는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18','K2-1-u2-X14']::text[],false,'{"seq":7,"concept":"K2-1-u2-C11","difficulty":3,"kind":"mc","stem":"떡집 주인이 말했어요. 「우리 떡은 쫀득쫀득하고 색깔이 알록달록해요.」 이 떡집에 어울리는 이름은 어느 것인가요?","options":[{"t":"쫀득쫀득 알록 떡집","correct":true},{"t":"떡 파는 집","mis":"K2-1-u2-X18"},{"t":"바삭바삭 떡집","mis":"K2-1-u2-X14"}],"explanation":["주인이 말한 특징 「쫀득쫀득」, 「알록달록」을 살렸어요.","「떡 파는 집」은 재미가 없어요.","떡은 바삭바삭하다고 하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"떡집 주인","text":"우리 떡은 쫀득쫀득하고 색깔이 알록달록해요."},{"who":"나","text":"그럼 이름에 그 특징을 넣어 볼까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#8','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'mc','auto','처음에 지은 「과자 가게」라는 이름을 「바삭바삭 오독오독 과자 가게」로 고쳤어요. 고친 이름이 더 좋아진 까닭은 무엇인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":8,"concept":"K2-1-u2-C11","difficulty":4,"kind":"mc","stem":"처음에 지은 「과자 가게」라는 이름을 「바삭바삭 오독오독 과자 가게」로 고쳤어요. 고친 이름이 더 좋아진 까닭은 무엇인가요?","options":[{"t":"과자 먹는 소리가 떠올라 재미있고 무엇을 파는지도 알 수 있어서","correct":true},{"t":"글자 수가 늘어 더 어려워져서","mis":"K2-1-u2-X18"},{"t":"과자 값을 알 수 있어서","mis":"K2-1-u2-X18"}],"explanation":["흉내 내는 말을 넣어 소리의 재미를 살렸어요.","「과자 가게」를 남겨 무엇을 파는지도 알 수 있어요.","글자 수나 값 때문에 좋아진 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#9','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'essay','teacher','내가 가게를 연다면 무엇을 팔지 정하고, 배운 방법으로 재미있는 이름을 지어 그 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":4,"kind":"essay","stem":"내가 가게를 연다면 무엇을 팔지 정하고, 배운 방법으로 재미있는 이름을 지어 그 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 붕어빵을 팔 거예요. 이름은 「바삭 말랑 붕어빵」이에요. 겉은 바삭하고 속은 말랑한 맛을 살렸어요.","scoring_points":["무엇을 팔지 썼는가","흉내 내는 말·되풀이·특징 가운데 하나 이상을 살려 이름을 지었는가","이름을 그렇게 지은 까닭을 썼는가"]},"explanation":["파는 것.","배운 방법.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_L12_challenge#10','kor',2,1,'u2','L12','g2_1_kor_u2_L12_challenge','lesson_challenge','K2-1-u2-C11',4,'essay','teacher','흉내 내는 말을 넣어 우리 모둠의 이름을 짓고, 그렇게 지은 까닭을 두 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u2-C11","difficulty":4,"kind":"essay","stem":"흉내 내는 말을 넣어 우리 모둠의 이름을 짓고, 그렇게 지은 까닭을 두 가지 써 보세요.","answer_guide":{"answer":"예: 「깡충깡충 토끼 모둠」 — 우리 모둠은 뛰어놀기를 좋아하고, 토끼처럼 서로 잘 도와주기 때문이에요.","scoring_points":["흉내 내는 말을 넣어 이름을 지었는가","까닭을 두 가지 썼는가","친구를 놀리는 말 없이 모두가 기분 좋은 이름인가"]},"explanation":["흉내 내는 말.","까닭 둘.","모두가 기분 좋은 이름."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#1','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C1',1,'mc','auto','가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"가랑비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["가늘게 내리는 비는 가랑비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#2','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C2',1,'mc','auto','「비」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「비」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"비행기","correct":true},{"t":"제비","mis":"K2-1-u2-X02"},{"t":"버섯","mis":"K2-1-u2-X03"}],"explanation":["비행기는 첫 글자가 「비」예요.","다른 낱말은 「비」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#3','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#4','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"오늘참좋다","correct":true},{"t":"안녕","mis":"K2-1-u2-X06"},{"t":"반가워친구야","mis":"K2-1-u2-X06"}],"explanation":["오·늘·참·좋·다, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#5','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"내 차례를 기다려요","correct":true},{"t":"친구 말을 끊고 먼저 말해요","mis":"K2-1-u2-X08"},{"t":"틀린 친구를 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#6','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C6',1,'mc','auto','부엌에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"부엌에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"국자","correct":true},{"t":"칠판","mis":"K2-1-u2-X10"},{"t":"그네","mis":"K2-1-u2-X10"}],"explanation":["국자는 부엌에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#7','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"맴맴","correct":true},{"t":"매미","mis":"K2-1-u2-X15"},{"t":"여름","mis":"K2-1-u2-X15"}],"explanation":["「맴맴」은 매미 소리를 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#8','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목","correct":true},{"t":"책의 값","mis":"K2-1-u2-X17"},{"t":"책을 산 가게","mis":"K2-1-u2-X17"}],"explanation":["제목을 알아야 친구가 그 책을 찾을 수 있어요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#9','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C11',2,'ox','auto','「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「가게1호」는 무엇을 파는지 잘 드러나는 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"무엇을 파는지도 소리의 재미도 없으니까","correct":true},{"t":"숫자가 들어가 기억하기 쉬우니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「가게1호」만 들어서는 무엇을 파는지 몰라요.","소리의 재미도 느껴지지 않아요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#10','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「시장에 가면 사과도 있고, 배도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「시장에 가면 사과도 있고, 배도 있고, 감도 있고」","correct":true},{"t":"「시장에 가면 감도 있고」","mis":"K2-1-u2-X07"},{"t":"「시장에 가면 배도 있고, 사과도 있고, 감도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#11','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「옛날에 곰이 살았어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「곰은 꿀을 좋아했어요.」","correct":true},{"t":"「자동차가 빵빵 울려요.」","mis":"K2-1-u2-X13"},{"t":"「곰 꿀 나무.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#12','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「리 · 구 · 개」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「리 · 구 · 개」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"개구리","correct":true},{"t":"구리개","mis":"K2-1-u2-X11"},{"t":"개리","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「개구리」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#13','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우는 무엇을 쓰고 걸었나요?","options":[{"t":"노란 우산","correct":true},{"t":"빨간 모자","mis":"K2-1-u2-X14"},{"t":"파란 비옷","mis":"K2-1-u2-X14"}],"explanation":["글에 「노란 우산을 쓰고」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#14','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',2,'ox','auto','같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"같은 글을 읽어도 사람마다 느낌이 다를 수 있어요.","answer":"O","reason_options":[{"t":"저마다 겪은 일과 생각이 다르니까","correct":true},{"t":"정답인 느낌은 하나뿐이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["읽는 사람마다 떠오르는 경험이 달라요.","그래서 느낌도 다를 수 있어요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#15','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"사과 · 사자 · 사탕","correct":true},{"t":"사과 · 과자 · 자두","mis":"K2-1-u2-X02"},{"t":"사과 · 소금 · 수박","mis":"K2-1-u2-X03"}],"explanation":["사과 · 사자 · 사탕은 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#16','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C11',2,'mc','auto','빵집에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"빵집에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"폭신폭신 빵집","correct":true},{"t":"빵집 1호","mis":"K2-1-u2-X18"},{"t":"먹는 곳","mis":"K2-1-u2-X18"}],"explanation":["「폭신폭신 빵집」은 부드러운 빵이 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#17','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',3,'error','auto','「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「하늘은 파래, 파라면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"준우 — 「파라면 사과」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"다은 — 「파라면 바다」","mis":"K2-1-u2-X19"},{"t":"서아 — 「파라면 청바지」","mis":"K2-1-u2-X19"}],"explanation":["사과는 파랗지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#18','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"냉장고에서 우유를 꺼냈어요.","correct":true},{"t":"아기 곰은 꿀을 정말 좋아했어요.","mis":"K2-1-u2-X19"},{"t":"어느 날 아기 곰은 커다란 벌집을 찾았어요.","mis":"K2-1-u2-X19"}],"explanation":["「냉장고에서 우유를 꺼냈어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["옛날에 아기 곰이 살았어요.","아기 곰은 꿀을 정말 좋아했어요.","냉장고에서 우유를 꺼냈어요.","어느 날 아기 곰은 커다란 벌집을 찾았어요."],"title":"아기 곰 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#19','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"데굴데굴","correct":true},{"t":"쌩쌩","mis":"K2-1-u2-X15"},{"t":"눈사람","mis":"K2-1-u2-X15"}],"explanation":["「데굴데굴」은 눈을 굴리는 모양이에요. 「쌩쌩」은 바람 소리, 「눈사람」은 이름이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#20','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"예린 — 「제목은 몰라요. 그냥 재미있어요.」","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"하준 — 「제가 좋아하는 책은 『작은 씨앗의 여행』이에요. 씨앗이 용감해서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지안 — 「좋아하는 문장은 ‘천천히 해도 괜찮아.’예요. 마음이 편해져서 좋아요.」","mis":"K2-1-u2-X19"}],"explanation":["예린이는 제목도 문장도 까닭도 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#21','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지우의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"비 오는 날이 즐거워요","correct":true},{"t":"천둥이 무서워 울고 싶어요","mis":"K2-1-u2-X16"},{"t":"비가 와서 심심해요","mis":"K2-1-u2-X16"}],"explanation":["지우는 「비 오는 날도 참 재미있다!」라고 말했어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#22','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C5',3,'mc','auto','꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"꼬리따기를 하는데 친구가 앞말과 관계없는 말을 했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「앞말에서 떠오르는 걸 다시 생각해 볼까?」","correct":true},{"t":"「그것도 몰라? 바보야.」","mis":"K2-1-u2-X09"},{"t":"「넌 빠져. 우리끼리 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#23','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#24','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C3',4,'essay','teacher','「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「하늘은 파래」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 하늘은 파래 → 파라면 바다 → 바다는 넓어 → 넓으면 운동장","scoring_points":["「하늘은 파래」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_a#25','kor',2,1,'u2','','g2_1_kor_u2_review_a','unit_review','K2-1-u2-C9',4,'essay','teacher','「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「첨벙첨벙 빗길」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.」 — 나도 장화를 신고 웅덩이를 밟으며 놀았던 일이 떠올라 재미있었어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["하늘이 우르르 쾅쾅 울렸어요.","굵은 빗방울이 후드득 떨어지기 시작했어요.","지우는 노란 우산을 쓰고 첨벙첨벙 걸었어요.","웅덩이마다 빗물이 찰랑찰랑 흔들렸어요.","「비 오는 날도 참 재미있다!」"],"title":"첨벙첨벙 빗길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#1','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C1',1,'mc','auto','굵고 세차게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"굵고 세차게 내리는 비를 무엇이라고 하나요?","options":[{"t":"장대비","correct":true},{"t":"이슬비","mis":"K2-1-u2-X01"},{"t":"가랑비","mis":"K2-1-u2-X01"}],"explanation":["굵고 세차게 내리는 비는 장대비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#2','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C2',1,'mc','auto','「사」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「사」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"사다리","correct":true},{"t":"감사","mis":"K2-1-u2-X02"},{"t":"소풍","mis":"K2-1-u2-X03"}],"explanation":["사다리는 첫 글자가 「사」예요.","다른 낱말은 「사」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#3','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#4','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"같이놀아요","correct":true},{"t":"놀자","mis":"K2-1-u2-X06"},{"t":"우리같이놀래요","mis":"K2-1-u2-X06"}],"explanation":["같·이·놀·아·요, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#5','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"친구 말을 끝까지 들어요","correct":true},{"t":"이기려고 혼자 계속 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말을 따라 하며 비웃어요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#6','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C6',1,'mc','auto','교실에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"교실에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"칠판","correct":true},{"t":"냄비","mis":"K2-1-u2-X10"},{"t":"시소","mis":"K2-1-u2-X10"}],"explanation":["칠판은 교실에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#7','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"깡충깡충","correct":true},{"t":"토끼","mis":"K2-1-u2-X15"},{"t":"뛰다","mis":"K2-1-u2-X15"}],"explanation":["「깡충깡충」은 토끼가 뛰는 모양을 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#8','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',1,'mc','auto','책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책을 소개할 때 꼭 들어가면 좋은 것은 어느 것인가요?","options":[{"t":"좋아하는 문장","correct":true},{"t":"책의 쪽수","mis":"K2-1-u2-X17"},{"t":"책의 무게","mis":"K2-1-u2-X17"}],"explanation":["좋아하는 문장을 말하면 책의 맛이 전해져요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#9','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C11',2,'ox','auto','「후루룩 국수」는 먹는 소리를 살린 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「후루룩 국수」는 먹는 소리를 살린 재미있는 이름이에요.","answer":"O","reason_options":[{"t":"국수 먹는 소리가 떠오르니까","correct":true},{"t":"이름이 짧으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「후루룩」은 국수 먹는 소리예요.","소리를 살리면 이름이 재미있어요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#10','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고, 기린도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「동물원에 가면 사자도 있고, 기린도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「동물원에 가면 사자도 있고, 기린도 있고, 코끼리도 있고」","correct":true},{"t":"「동물원에 가면 코끼리도 있고」","mis":"K2-1-u2-X07"},{"t":"「동물원에 가면 기린도 있고, 코끼리도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#11','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「어느 날 다람쥐가 도토리를 주웠어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「다람쥐는 도토리를 나무 구멍에 숨겼어요.」","correct":true},{"t":"「비행기가 하늘을 날아요.」","mis":"K2-1-u2-X13"},{"t":"「다람쥐 도토리 구멍.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#12','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「끼 · 코 · 리」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「끼 · 코 · 리」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"코끼리","correct":true},{"t":"끼코리","mis":"K2-1-u2-X11"},{"t":"코리","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「코끼리」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#13','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 민지는 누구와 연을 날렸나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 민지는 누구와 연을 날렸나요?","options":[{"t":"아빠","correct":true},{"t":"엄마","mis":"K2-1-u2-X14"},{"t":"동생","mis":"K2-1-u2-X14"}],"explanation":["글에 「민지는 아빠와 연을 날렸어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#14','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',2,'ox','auto','느낌을 말할 때 「재미있었어.」라고만 말하면 충분해요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"느낌을 말할 때 「재미있었어.」라고만 말하면 충분해요.","answer":"X","reason_options":[{"t":"어느 장면이 왜 재미있었는지 말해야 잘 전해지니까","correct":true},{"t":"느낌은 짧을수록 좋으니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["까닭이 없으면 느낌이 잘 전해지지 않아요.","「~해서 재미있었어.」처럼 말해요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#15','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"고래 · 고구마 · 고양이","correct":true},{"t":"고구마 · 마늘 · 늘보","mis":"K2-1-u2-X02"},{"t":"고래 · 기차 · 구두","mis":"K2-1-u2-X03"}],"explanation":["고래 · 고구마 · 고양이는 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#16','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C11',2,'mc','auto','튀김 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"튀김 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"바삭바삭 튀김","correct":true},{"t":"튀김 가게 2번","mis":"K2-1-u2-X18"},{"t":"파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「바삭바삭 튀김」은 튀김 씹는 소리가 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#17','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',3,'error','auto','「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「눈은 하얘, 하야면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"도윤 — 「하야면 토마토」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"하린 — 「하야면 구름」","mis":"K2-1-u2-X19"},{"t":"예린 — 「하야면 우유」","mis":"K2-1-u2-X19"}],"explanation":["토마토는 하얗지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#18','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"버스가 정류장에 멈췄어요.","correct":true},{"t":"거북이는 엉금엉금 바다로 걸어갔어요.","mis":"K2-1-u2-X19"},{"t":"파도를 만난 거북이는 신나게 헤엄쳤어요.","mis":"K2-1-u2-X19"}],"explanation":["「버스가 정류장에 멈췄어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["작은 거북이가 바닷가에서 태어났어요.","거북이는 엉금엉금 바다로 걸어갔어요.","버스가 정류장에 멈췄어요.","파도를 만난 거북이는 신나게 헤엄쳤어요."],"title":"작은 거북이 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#19','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"쏙쏙","correct":true},{"t":"깔깔","mis":"K2-1-u2-X15"},{"t":"찰박찰박","mis":"K2-1-u2-X15"}],"explanation":["「쏙쏙」은 물고기가 빠르게 지나가는 모양이에요. 「깔깔」·「찰박찰박」은 소리예요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#20','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"현우 — 책 세 쪽을 그대로 옮겨 적은 책갈피를 보여 주었어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"소율 — 좋아하는 문장 한 줄을 적은 책갈피를 보여 주었어요","mis":"K2-1-u2-X19"},{"t":"서아 — 문장 한 줄과 작은 그림을 그린 책갈피를 보여 주었어요","mis":"K2-1-u2-X19"}],"explanation":["책갈피에는 짧은 문장 한 줄이 알맞아요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#21','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 연이 날아갈 때 민지의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 연이 날아갈 때 민지의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"아쉽지만 연에게 인사할 만큼 씩씩해요","correct":true},{"t":"아빠에게 화가 났어요","mis":"K2-1-u2-X16"},{"t":"연이 날아가서 신이 나 춤을 춰요","mis":"K2-1-u2-X16"}],"explanation":["민지는 「안녕, 내 연아!」 하고 손을 흔들었어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#22','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C5',3,'mc','auto','말 덧붙이기를 하는데 친구가 앞말 하나를 빠뜨렸어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"말 덧붙이기를 하는데 친구가 앞말 하나를 빠뜨렸어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「배도 있었어. 같이 다시 말해 보자.」","correct":true},{"t":"「하하, 또 틀렸다!」","mis":"K2-1-u2-X09"},{"t":"「너 때문에 졌잖아. 이제 내가 다 할게.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#23','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#24','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C3',4,'essay','teacher','「사과는 빨개」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「사과는 빨개」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 사과는 빨개 → 빨가면 딸기 → 딸기는 달아 → 달면 사탕","scoring_points":["「사과는 빨개」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_b#25','kor',2,1,'u2','','g2_1_kor_u2_review_b','unit_review','K2-1-u2-C9',4,'essay','teacher','「훨훨 날아간 연」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「훨훨 날아간 연」을 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「연은 빙글빙글 돌며 멀리 날아갔어요.」 — 연이 춤추듯 날아가는 모습이 떠올라 재미있었지만 조금 아쉬웠어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#1','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C1',1,'mc','auto','꼭 필요할 때 내려 반가운 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"꼭 필요할 때 내려 반가운 비를 무엇이라고 하나요?","options":[{"t":"단비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"이슬비","mis":"K2-1-u2-X01"}],"explanation":["꼭 필요할 때 내리는 비는 단비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#2','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C2',1,'mc','auto','「나」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「나」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"나무","correct":true},{"t":"바나나","mis":"K2-1-u2-X02"},{"t":"너구리","mis":"K2-1-u2-X03"}],"explanation":["나무는 첫 글자가 「나」예요.","다른 낱말은 「나」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#3','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#4','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"사랑해친구","correct":true},{"t":"사랑해","mis":"K2-1-u2-X06"},{"t":"정말정말사랑해","mis":"K2-1-u2-X06"}],"explanation":["사·랑·해·친·구, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#5','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"친구가 막히면 기다려 줘요","correct":true},{"t":"「빨리 해!」 하고 재촉하며 끼어들어요","mis":"K2-1-u2-X08"},{"t":"「그것도 못 해?」 하고 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#6','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C6',1,'mc','auto','놀이터에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"놀이터에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"미끄럼틀","correct":true},{"t":"도마","mis":"K2-1-u2-X10"},{"t":"분필","mis":"K2-1-u2-X10"}],"explanation":["미끄럼틀은 놀이터에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#7','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',1,'mc','auto','소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"멍멍","correct":true},{"t":"강아지","mis":"K2-1-u2-X15"},{"t":"짖다","mis":"K2-1-u2-X15"}],"explanation":["「멍멍」은 강아지 소리를 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#8','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',1,'mc','auto','책갈피에 적기 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"책갈피에 적기 좋은 것은 어느 것인가요?","options":[{"t":"마음에 드는 문장 한 줄","correct":true},{"t":"책 한 쪽 전체","mis":"K2-1-u2-X17"},{"t":"책값과 날짜","mis":"K2-1-u2-X17"}],"explanation":["책갈피에는 짧은 문장 한 줄이 어울려요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#9','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C11',2,'ox','auto','「음식 파는 곳」은 특징을 잘 살린 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「음식 파는 곳」은 특징을 잘 살린 재미있는 이름이에요.","answer":"X","reason_options":[{"t":"어떤 음식인지 특징이 드러나지 않으니까","correct":true},{"t":"음식을 판다고 말했으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「음식 파는 곳」은 무엇을 파는지 알 수 없어요.","맛이나 모양이 드러나야 해요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#10','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「바닷가에 가면 조개도 있고, 게도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「바닷가에 가면 조개도 있고, 게도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷가에 가면 조개도 있고, 게도 있고, 모래도 있고」","correct":true},{"t":"「바닷가에 가면 모래도 있고」","mis":"K2-1-u2-X07"},{"t":"「바닷가에 가면 게도 있고, 조개도 있고, 모래도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#11','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「아기 펭귄은 헤엄을 못 쳤어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「아기 펭귄은 헤엄을 못 쳤어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그래서 엄마 펭귄에게 헤엄을 배웠어요.」","correct":true},{"t":"「사과는 빨개요.」","mis":"K2-1-u2-X13"},{"t":"「펭귄 바다 물.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#12','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「나 · 바 · 나」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「나 · 바 · 나」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"바나나","correct":true},{"t":"나바나","mis":"K2-1-u2-X11"},{"t":"바나","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「바나나」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#13','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 할머니 댁 마당에 병아리가 몇 마리 있나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니 댁 마당에 병아리가 몇 마리 있나요?","options":[{"t":"다섯 마리","correct":true},{"t":"세 마리","mis":"K2-1-u2-X14"},{"t":"열 마리","mis":"K2-1-u2-X14"}],"explanation":["글에 「병아리 다섯 마리가 있어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#14','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',2,'ox','auto','친구가 나와 다른 느낌을 말하면 틀렸다고 알려 줘요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"친구가 나와 다른 느낌을 말하면 틀렸다고 알려 줘요.","answer":"X","reason_options":[{"t":"느낌은 사람마다 다를 수 있으니까","correct":true},{"t":"내 느낌이 정답이니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["다른 느낌은 틀린 것이 아니에요.","「그렇게 느낄 수도 있구나.」 하고 들어요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#15','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"바다 · 바지 · 바람","correct":true},{"t":"바지 · 지구 · 구두","mis":"K2-1-u2-X02"},{"t":"바다 · 버섯 · 보리","mis":"K2-1-u2-X03"}],"explanation":["바다 · 바지 · 바람은 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#16','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C11',2,'mc','auto','찌개 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"찌개 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"보글보글 찌개","correct":true},{"t":"찌개 3호","mis":"K2-1-u2-X18"},{"t":"음식점","mis":"K2-1-u2-X18"}],"explanation":["「보글보글 찌개」는 찌개 끓는 소리가 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#17','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',3,'error','auto','「기차는 길어, 길면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「기차는 길어, 길면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"민호 — 「길면 동전」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"지안 — 「길면 뱀」","mis":"K2-1-u2-X19"},{"t":"소율 — 「길면 기린 목」","mis":"K2-1-u2-X19"}],"explanation":["동전은 길지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#18','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"연필을 깎아 필통에 넣었어요.","correct":true},{"t":"꼬마 여우는 친구를 사귀고 싶었어요.","mis":"K2-1-u2-X19"},{"t":"꼬마 여우는 다람쥐에게 「같이 놀자!」 하고 말했어요.","mis":"K2-1-u2-X19"}],"explanation":["「연필을 깎아 필통에 넣었어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["숲속에 꼬마 여우가 살았어요.","꼬마 여우는 친구를 사귀고 싶었어요.","연필을 깎아 필통에 넣었어요.","꼬마 여우는 다람쥐에게 「같이 놀자!」 하고 말했어요."],"title":"꼬마 여우 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#19','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"쌩쌩","correct":true},{"t":"훨훨","mis":"K2-1-u2-X15"},{"t":"빙글빙글","mis":"K2-1-u2-X15"}],"explanation":["「쌩쌩」은 바람 소리예요. 「훨훨」·「빙글빙글」은 모양이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["바람이 쌩쌩 부는 날, 민지는 아빠와 연을 날렸어요.","연은 하늘 높이 훨훨 날아올랐어요.","그런데 갑자기 연줄이 툭 끊어졌어요.","연은 빙글빙글 돌며 멀리 날아갔어요.","민지는 「안녕, 내 연아!」 하고 손을 흔들었어요."],"title":"훨훨 날아간 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#20','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"태민 — 「재밌어요.」라고만 말하고 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"은솔 — 제목, 좋아하는 문장, 까닭을 차례로 말했어요","mis":"K2-1-u2-X19"},{"t":"하람 — 친구들을 보며 좋아하는 문장을 또박또박 읽었어요","mis":"K2-1-u2-X19"}],"explanation":["태민이는 제목도 문장도 까닭도 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#21','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 아린이의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 아린이의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"병아리가 귀여워 기뻐요","correct":true},{"t":"병아리가 무서워요","mis":"K2-1-u2-X16"},{"t":"병아리가 미워요","mis":"K2-1-u2-X16"}],"explanation":["아린이는 병아리가 귀여워 방긋 웃었어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#22','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C5',3,'mc','auto','다섯 글자 말놀이에서 친구가 여섯 글자로 말했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"다섯 글자 말놀이에서 친구가 여섯 글자로 말했어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「한 글자만 빼면 딱 맞겠다!」","correct":true},{"t":"「글자도 못 세냐?」","mis":"K2-1-u2-X09"},{"t":"「이번엔 내가 대신 말할게. 넌 듣기만 해.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#23','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#24','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C3',4,'essay','teacher','「눈은 하얘」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「눈은 하얘」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 눈은 하얘 → 하야면 우유 → 우유는 고소해 → 고소하면 참깨","scoring_points":["「눈은 하얘」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_c#25','kor',2,1,'u2','','g2_1_kor_u2_review_c','unit_review','K2-1-u2-C9',4,'essay','teacher','「졸졸 병아리」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「졸졸 병아리」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.」 — 동생이 나를 졸졸 따라다니는 모습이 떠올라 웃음이 났어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#1','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C1',1,'mc','auto','이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?',ARRAY['K2-1-u2-X01']::text[],false,'{"seq":1,"concept":"K2-1-u2-C1","difficulty":1,"kind":"mc","stem":"이슬처럼 아주 가늘게 내리는 비를 무엇이라고 하나요?","options":[{"t":"이슬비","correct":true},{"t":"장대비","mis":"K2-1-u2-X01"},{"t":"단비","mis":"K2-1-u2-X01"}],"explanation":["이슬처럼 아주 가늘게 내리는 비는 이슬비예요.","비가 내리는 모습에 따라 이름이 달라요.","이름에는 그렇게 부르는 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#2','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C2',1,'mc','auto','「고」로 시작하는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":2,"concept":"K2-1-u2-C2","difficulty":1,"kind":"mc","stem":"「고」로 시작하는 낱말은 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"사고","mis":"K2-1-u2-X02"},{"t":"구름","mis":"K2-1-u2-X03"}],"explanation":["고양이는 첫 글자가 「고」예요.","다른 낱말은 「고」가 끝에 있거나 다른 글자로 시작해요.","맨 앞 글자를 손가락으로 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#3','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',1,'blank','auto','꼬리따기 말놀이를 해요. 빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#4','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C4',1,'mc','auto','다섯 글자로 된 말은 어느 것인가요?',ARRAY['K2-1-u2-X06']::text[],false,'{"seq":4,"concept":"K2-1-u2-C4","difficulty":1,"kind":"mc","stem":"다섯 글자로 된 말은 어느 것인가요?","options":[{"t":"힘내우리반","correct":true},{"t":"힘내","mis":"K2-1-u2-X06"},{"t":"우리반모두힘내자","mis":"K2-1-u2-X06"}],"explanation":["힘·내·우·리·반, 다섯 글자예요.","다른 말은 다섯 글자보다 적거나 많아요.","글자 하나에 손가락 하나씩 접어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#5','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C5',1,'mc','auto','말놀이를 바르게 하는 모습은 어느 것인가요?',ARRAY['K2-1-u2-X08','K2-1-u2-X09']::text[],false,'{"seq":5,"concept":"K2-1-u2-C5","difficulty":1,"kind":"mc","stem":"말놀이를 바르게 하는 모습은 어느 것인가요?","options":[{"t":"이기기보다 함께 즐겨요","correct":true},{"t":"내 차례가 아닌데 큰 소리로 말해요","mis":"K2-1-u2-X08"},{"t":"친구 말에 「틀렸지롱!」 하고 놀려요","mis":"K2-1-u2-X09"}],"explanation":["차례를 지키고 함께 즐겨야 말놀이가 재미있어요.","끼어들거나 놀리면 놀이가 즐겁지 않아요.","친구 말을 끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#6','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C6',1,'mc','auto','공원에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X10']::text[],false,'{"seq":6,"concept":"K2-1-u2-C6","difficulty":1,"kind":"mc","stem":"공원에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"비둘기","correct":true},{"t":"칫솔","mis":"K2-1-u2-X10"},{"t":"책상","mis":"K2-1-u2-X10"}],"explanation":["비둘기는 공원에서 볼 수 있어요.","다른 낱말은 다른 장소에서 볼 수 있어요.","그 장소에 서 있다고 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#7','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',1,'mc','auto','모양을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":7,"concept":"K2-1-u2-C8","difficulty":1,"kind":"mc","stem":"모양을 흉내 낸 말은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"거북이","mis":"K2-1-u2-X15"},{"t":"느리다","mis":"K2-1-u2-X15"}],"explanation":["「엉금엉금」은 거북이가 기는 모양을 흉내 낸 말이에요.","다른 두 낱말은 흉내 내는 말이 아니에요.","따라 했을 때 소리나 모습이 떠오르는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#8','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',1,'mc','auto','좋아하는 문장을 소개한 뒤 덧붙이면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u2-X17']::text[],false,'{"seq":8,"concept":"K2-1-u2-C10","difficulty":1,"kind":"mc","stem":"좋아하는 문장을 소개한 뒤 덧붙이면 좋은 것은 어느 것인가요?","options":[{"t":"그 문장을 좋아하는 까닭","correct":true},{"t":"책 표지의 색깔","mis":"K2-1-u2-X17"},{"t":"책을 읽은 시간","mis":"K2-1-u2-X17"}],"explanation":["까닭을 말하면 친구가 내 마음을 알 수 있어요.","다른 것은 책을 소개하는 데 중요하지 않아요.","제목 → 좋아하는 문장 → 까닭으로 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#9','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C11',2,'ox','auto','「매콤달콤 떡볶이」는 맛이 떠오르는 재미있는 이름이에요.',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":9,"concept":"K2-1-u2-C11","difficulty":2,"kind":"ox","stem":"「매콤달콤 떡볶이」는 맛이 떠오르는 재미있는 이름이에요.","answer":"O","reason_options":[{"t":"떡볶이의 맛을 살렸으니까","correct":true},{"t":"글자가 많으니까","mis":"K2-1-u2-X18"}],"mis":"K2-1-u2-X18","explanation":["「매콤달콤」은 떡볶이 맛을 떠올리게 해요.","특징을 살리면 이름이 재미있어요.","특징과 흉내 내는 말을 살려 이름을 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#10','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C4',2,'mc','auto','말 덧붙이기 놀이를 해요. 앞 친구가 「교실에 가면 칠판도 있고, 책상도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X07']::text[],false,'{"seq":10,"concept":"K2-1-u2-C4","difficulty":2,"kind":"mc","stem":"말 덧붙이기 놀이를 해요. 앞 친구가 「교실에 가면 칠판도 있고, 책상도 있고」라고 했어요. 내 차례에 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「교실에 가면 칠판도 있고, 책상도 있고, 필통도 있고」","correct":true},{"t":"「교실에 가면 필통도 있고」","mis":"K2-1-u2-X07"},{"t":"「교실에 가면 책상도 있고, 필통도 있고」","mis":"K2-1-u2-X07"}],"explanation":["앞 친구 말을 그대로 말하고 끝에 하나를 더해요.","앞말을 빠뜨리거나 차례를 바꾸면 안 돼요.","하나씩 늘어나는 재미가 말 덧붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#11','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C7',2,'mc','auto','친구가 「꼬마 토끼가 길을 잃었어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X13','K2-1-u2-X12']::text[],false,'{"seq":11,"concept":"K2-1-u2-C7","difficulty":2,"kind":"mc","stem":"친구가 「꼬마 토끼가 길을 잃었어요.」라고 말했어요. 이어질 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「꼬마 토끼는 부엉이에게 길을 물었어요.」","correct":true},{"t":"「냄비에서 물이 끓어요.」","mis":"K2-1-u2-X13"},{"t":"「토끼 길 부엉이.」","mis":"K2-1-u2-X12"}],"explanation":["앞 문장의 인물 이야기를 이어 가요.","관계없는 문장이나 낱말만 늘어놓은 말은 이야기를 끊어요.","앞 문장의 인물을 넣어 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#12','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C6',2,'mc','auto','뒤섞인 글자 「기 · 행 · 비」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?',ARRAY['K2-1-u2-X11']::text[],false,'{"seq":12,"concept":"K2-1-u2-C6","difficulty":2,"kind":"mc","stem":"뒤섞인 글자 「기 · 행 · 비」를 모두 한 번씩 써서 만든 낱말은 어느 것인가요?","options":[{"t":"비행기","correct":true},{"t":"행비기","mis":"K2-1-u2-X11"},{"t":"비기","mis":"K2-1-u2-X11"}],"explanation":["글자를 맞추면 「비행기」가 돼요.","차례를 잘못 놓거나 글자를 빠뜨리면 안 돼요.","글자 카드를 하나씩 지우며 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#13','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',2,'mc','auto','글을 읽고 답해 보세요. 하준이는 어디에 갔나요?',ARRAY['K2-1-u2-X14']::text[],false,'{"seq":13,"concept":"K2-1-u2-C8","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 하준이는 어디에 갔나요?","options":[{"t":"시냇가","correct":true},{"t":"바닷가","mis":"K2-1-u2-X14"},{"t":"수영장","mis":"K2-1-u2-X14"}],"explanation":["글에 「하준이는 시냇가에 갔어요」라고 나와 있어요.","다른 보기는 글에 나오지 않거나 다른 것이에요.","글에서 찾아 손가락으로 짚어요."],"asset":{"type":"passage","lines":["여름 방학에 하준이는 시냇가에 갔어요.","차가운 물에 발을 담그자 「앗, 차가워!」 소리가 절로 났어요.","작은 물고기들이 발가락 사이로 쏙쏙 지나갔어요.","하준이는 깔깔 웃으며 물을 찰박찰박 찼어요."],"title":"찰박찰박 시냇가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#14','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',2,'ox','auto','글을 읽고 떠오른 내 경험을 까닭으로 들어 느낌을 말하면 좋아요.',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":14,"concept":"K2-1-u2-C9","difficulty":2,"kind":"ox","stem":"글을 읽고 떠오른 내 경험을 까닭으로 들어 느낌을 말하면 좋아요.","answer":"O","reason_options":[{"t":"왜 그렇게 느꼈는지 친구가 알 수 있으니까","correct":true},{"t":"경험은 글과 관계없으니까","mis":"K2-1-u2-X16"}],"mis":"K2-1-u2-X16","explanation":["내 경험을 까닭으로 들면 느낌이 잘 전해져요.","「나도 ~한 적이 있어서」처럼 말해요.","까닭을 들어 느낌을 말하고 친구 느낌도 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#15','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C2',2,'mc','auto','첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u2-X02','K2-1-u2-X03']::text[],false,'{"seq":15,"concept":"K2-1-u2-C2","difficulty":2,"kind":"mc","stem":"첫 글자가 같은 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"가방 · 가위 · 가지","correct":true},{"t":"가지 · 지도 · 도토리","mis":"K2-1-u2-X02"},{"t":"가방 · 거미 · 고추","mis":"K2-1-u2-X03"}],"explanation":["가방 · 가위 · 가지는 모두 첫 글자가 같아요.","끝 글자를 이은 것이나 자음자만 같은 것은 첫 글자가 같은 것이 아니에요.","맨 앞 글자를 모두 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#16','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C11',2,'mc','auto','과일 가게에 어울리는 재미있는 이름은 어느 것인가요?',ARRAY['K2-1-u2-X18']::text[],false,'{"seq":16,"concept":"K2-1-u2-C11","difficulty":2,"kind":"mc","stem":"과일 가게에 어울리는 재미있는 이름은 어느 것인가요?","options":[{"t":"새콤달콤 과일","correct":true},{"t":"과일 4번","mis":"K2-1-u2-X18"},{"t":"물건 파는 곳","mis":"K2-1-u2-X18"}],"explanation":["「새콤달콤 과일」은 과일 맛이 떠올라요.","다른 이름은 무엇을 파는지나 재미가 드러나지 않아요.","특징과 흉내 내는 말을 살려 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#17','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',3,'error','auto','「얼음은 차가워, 차가우면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?',ARRAY['K2-1-u2-X04','K2-1-u2-X19']::text[],false,'{"seq":17,"concept":"K2-1-u2-C3","difficulty":3,"kind":"error","stem":"「얼음은 차가워, 차가우면 …」 다음 말을 이어 꼬리따기를 했어요. 잘못 이은 친구는 누구인가요?","options":[{"t":"태민 — 「차가우면 난로」","correct":true,"mis_target":"K2-1-u2-X04"},{"t":"서윤 — 「차가우면 눈사람」","mis":"K2-1-u2-X19"},{"t":"시우 — 「차가우면 아이스크림」","mis":"K2-1-u2-X19"}],"explanation":["난로는 차갑지 않아요.","다른 두 친구는 앞말에서 떠오르는 것을 이었어요.","바로 앞말에서 떠오르는 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#18','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C7',3,'mc','auto','친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?',ARRAY['K2-1-u2-X19']::text[],false,'{"seq":18,"concept":"K2-1-u2-C7","difficulty":3,"kind":"mc","stem":"친구들과 만든 줄줄이 이야기예요. 이야기와 이어지지 않는 문장은 어느 것인가요?","options":[{"t":"운동장에서 축구 시합이 열렸어요.","correct":true},{"t":"처음에는 자꾸 떨어질 뻔했어요.","mis":"K2-1-u2-X19"},{"t":"드디어 아기 새가 하늘을 훨훨 날았어요.","mis":"K2-1-u2-X19"}],"explanation":["「운동장에서 축구 시합이 열렸어요」는 이야기와 관계가 없어요.","다른 문장은 모두 같은 인물의 일을 이어 가요.","앞 문장의 인물을 넣어 이어야 이야기가 돼요."],"asset":{"type":"passage","lines":["아기 새가 둥지에서 날갯짓을 연습했어요.","처음에는 자꾸 떨어질 뻔했어요.","운동장에서 축구 시합이 열렸어요.","드디어 아기 새가 하늘을 훨훨 날았어요."],"title":"아기 새 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#19','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C8',3,'mc','auto','글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u2-X15']::text[],false,'{"seq":19,"concept":"K2-1-u2-C8","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 소리를 흉내 낸 말은 어느 것인가요?","options":[{"t":"삐악삐악","correct":true},{"t":"졸졸","mis":"K2-1-u2-X15"},{"t":"방긋","mis":"K2-1-u2-X15"}],"explanation":["「삐악삐악」은 병아리 소리예요. 「졸졸」·「방긋」은 모양이에요.","흉내 내는 말이 무엇의 소리인지, 모양인지 따라 해 보며 가려요.","흉내 내는 말은 글을 생생하게 만들어요."],"asset":{"type":"passage","lines":["할머니 댁 마당에 병아리 다섯 마리가 있어요.","병아리들은 삐악삐악 울며 엄마 닭을 졸졸 따라다녀요.","아린이가 모이를 뿌리자 병아리들이 콕콕 쪼아 먹었어요.","아린이는 병아리들이 귀여워 방긋 웃었어요."],"title":"졸졸 병아리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#20','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',3,'error','auto','친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?',ARRAY['K2-1-u2-X17','K2-1-u2-X19']::text[],false,'{"seq":20,"concept":"K2-1-u2-C10","difficulty":3,"kind":"error","stem":"친구들이 좋아하는 책을 소개했어요. 알맞지 않게 소개한 친구는 누구인가요?","options":[{"t":"도담 — 「좋아하는 문장은 ‘나는 할 수 있어!’예요.」 하고 까닭 없이 들어갔어요","correct":true,"mis_target":"K2-1-u2-X17"},{"t":"아린 — 「‘나는 할 수 있어!’를 읽으면 힘이 나서 좋아요.」","mis":"K2-1-u2-X19"},{"t":"지후 — 「제가 좋아하는 책은 『용감한 토끼』예요.」로 시작했어요","mis":"K2-1-u2-X19"}],"explanation":["도담이는 그 문장을 좋아하는 까닭을 말하지 않았어요.","다른 두 친구는 알맞게 소개했어요.","제목 → 좋아하는 문장 → 까닭을 담아 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#21','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',3,'mc','auto','글을 읽고 답해 보세요. 도윤이의 마음을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K2-1-u2-X16']::text[],false,'{"seq":21,"concept":"K2-1-u2-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 도윤이의 마음을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"눈사람을 만들며 신나요","correct":true},{"t":"추워서 집에 가고 싶어요","mis":"K2-1-u2-X16"},{"t":"동생에게 화가 났어요","mis":"K2-1-u2-X16"}],"explanation":["찬 바람에도 두 볼이 따끈따끈할 만큼 신나게 놀았어요.","일과 반대되거나 글에 없는 마음은 알맞지 않아요.","인물이 한 말과 행동에서 마음을 찾아요."],"asset":{"type":"passage","lines":["밤새 하얀 눈이 펑펑 내렸어요.","도윤이와 동생은 눈을 데굴데굴 굴려 눈사람을 만들었어요.","코에는 당근을, 눈에는 단추를 꾹꾹 눌러 붙였어요.","찬 바람이 쌩쌩 불었지만 두 볼은 따끈따끈했어요."],"title":"데굴데굴 눈사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#22','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C5',3,'mc','auto','첫 글자 말놀이에서 친구가 한참 생각하고 있어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u2-X09','K2-1-u2-X08']::text[],false,'{"seq":22,"concept":"K2-1-u2-C5","difficulty":3,"kind":"mc","stem":"첫 글자 말놀이에서 친구가 한참 생각하고 있어요. 내가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「천천히 생각해. 기다릴게.」","correct":true},{"t":"「너무 느려! 거북이냐?」","mis":"K2-1-u2-X09"},{"t":"「시간 끝! 내 차례야.」","mis":"K2-1-u2-X08"}],"explanation":["친구가 다시 해 볼 수 있게 부드럽게 말해요.","놀리거나 빼 버리면 친구가 속상해요.","함께 즐기는 것이 말놀이의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#23','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C10',4,'mc','auto','두 친구가 책을 소개했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#24','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C3',4,'essay','teacher','「기차는 길어」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u2-C3","difficulty":4,"kind":"essay","stem":"「기차는 길어」로 시작해 꼬리따기를 네 마디로 이어 써 보세요.","answer_guide":{"answer":"예: 기차는 길어 → 길면 뱀 → 뱀은 무서워 → 무서우면 호랑이","scoring_points":["「기차는 길어」로 시작했는가","마디마다 바로 앞말에서 떠오르는 말을 이었는가","네 마디를 썼는가"]},"explanation":["시작 말.","앞말에서 잇기.","네 마디."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u2_review_d#25','kor',2,1,'u2','','g2_1_kor_u2_review_d','unit_review','K2-1-u2-C9',4,'essay','teacher','「지글지글 부침개」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u2-C9","difficulty":4,"kind":"essay","stem":"「지글지글 부침개」를 읽고 가장 재미있었던 문장을 하나 옮겨 쓰고, 그 까닭이나 떠오른 내 경험을 써 보세요.","answer_guide":{"answer":"예: 「아빠, 빗소리랑 부침개 소리가 똑같아요!」 — 정말 그런지 다음에 비 오는 날 들어 보고 싶어졌어요.","scoring_points":["글에 있는 문장을 골라 썼는가","그 문장을 고른 까닭이나 떠오른 경험을 썼는가","내 생각이나 느낌이 드러나는가"]},"explanation":["글의 문장.","까닭·경험.","내 느낌."],"asset":{"type":"passage","lines":["비 오는 저녁, 아빠가 부침개를 부치셨어요.","팬에서 지글지글 소리가 났어요.","서아는 바삭바삭한 끝부분을 호호 불어 먹었어요.","「아빠, 빗소리랑 부침개 소리가 똑같아요!」"],"title":"지글지글 부침개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
